{
  "name": "coucou-windows",
  "private": true,
  "version": "0.5.9",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "preview": "vite preview",
    "test": "node --import ./tests/setup.mjs --test \"tests/**/*.test.mjs\"",
    "icons": "node scripts/gen-icons.mjs",
    "tauri": "tauri",
    "predev": "cargo build --release -p coucou-hook",
    "prebuild": "cargo build --release -p coucou-hook",
    "pack": "tauri build && node scripts/pack.mjs",
    "hotfix": "tauri build --no-bundle && node scripts/hotfix.mjs"
  },
  "devDependencies": {
    "@tauri-apps/cli": "^2",
    "typescript": "^5.6.0",
    "vite": "^6"
  },
  "dependencies": {
    "@tauri-apps/api": "^2"
  }
}

import { setAppName } from "./core/branding";
// Entry point: boot the bridge, wire the island, start the greeting.

import "./style.css";
import { Bridge, IS_TAURI, onEvent } from "./core/bridge";
import { Sound } from "./core/sound";
import { State, type Settings } from "./core/state";
import { Island } from "./island/island";
import { registerHookHandlers } from "./island/hooks";
import { registerPhoneLink } from "./island/phone-link";
import { registerIntegrationHandlers, refreshConfigured } from "./island/integrations";
import { registerShortcutHandlers } from "./island/shortcuts";
import { registerVoiceHandlers } from "./island/voice";
import { applySpotify, registerSpotifyHandlers } from "./island/spotify";
import { registerWhatsAppHandlers } from "./island/whatsapp";
import { SPOTIFY_ID } from "./core/spotify";
import { Recap } from "./recap/recap";
import { Updates } from "./island/update";
import { WhatsNew } from "./whats-new/controller";
import { onLanguageChange, refreshLabels, resolveLanguage, setLanguage, systemLanguages } from "./i18n/i18n";

/** Shows the language Settings asks for ("" = the system's, when Coucou has it). */
function applyLanguage() {
  if (setAppName(State.settings.appName)) refreshLabels();
  setLanguage(resolveLanguage(State.settings.language, systemLanguages()));
}

async function main() {
  const root = document.getElementById("root");
  if (!root) return;

  void Sound.preload();

  // Before the island exists: its canvases size their bitmaps from the pixel
  // ratio once, so the zoom correction has to land first. If zoom was adjusted,
  // wait until the ratio updates (or up to 500ms) so nothing is sized against
  // the stale value.
  const dprBefore = window.devicePixelRatio || 1;
  const zoomChanged = await Bridge.fitZoom(dprBefore);
  if (zoomChanged) {
    for (let i = 0; i < 20 && window.devicePixelRatio === dprBefore; i++) {
      await new Promise((r) => setTimeout(r, 25));
    }
  }

  const island = new Island(root);
  // The dev previews (dev/*.html) drive the island from the console.
  if (import.meta.env.DEV) Object.assign(window, { __island: island, __state: State });

  const boot = await Bridge.boot();
  if (boot) {
    State.settings = { ...State.settings, ...boot.settings };
  }
  // A language change redraws the island in place: the texts given as tl(…)
  // relabel themselves (views/dom.ts) and the views redraw the rest on this
  // sync. Nothing is rebuilt, so tasks, steps and the chat stay as they are.
  onLanguageChange(() => State.notify());
  applyLanguage();
  // Rust shows the tray and its errors in the same language as the webview.
  void Bridge.setSystemLanguages(systemLanguages());
  island.applySettings();
  State.loadIntegrationTasks();
  if (boot && !boot.cursorPoll) island.followPageCursor();
  await island.desktop.init();

  await onEvent<{ x: number; y: number }>("cursor", ({ x, y }) => island.onCursor(x, y));
  await onEvent<boolean>("pointer-inside", (inside) => island.setPointerInside(inside));
  await onEvent<null>("closed-hover", () => island.wakeFromClosed());

  /** Pause has to reach Rust too, or the pollers keep calling out. */
  const setPaused = (on: boolean) => {
    if (State.paused === on) return;
    State.paused = on;
    void Bridge.setPaused(on);
  };

  await onEvent<string>("tray", (what) => {
    switch (what) {
      case "settings":
        setPaused(false);
        island.alert("settings");
        break;
      case "open":
        setPaused(false);
        island.alert(State.defaultView());
        break;
      case "recap":
        setPaused(false);
        void Recap.open(island);
        break;
      case "wardrobe":
        setPaused(false);
        island.alert("wardrobe");
        break;
      // "Update Coucou to X…", only in the menu while a new version is out.
      case "update":
        setPaused(false);
        Updates.show();
        break;
      case "pause":
        setPaused(!State.paused);
        if (State.paused) island.fsm.forceHidden();
        else island.reveal();
        break;
    }
  });

  const checkZoom = async () => {
    const dpr = window.devicePixelRatio || 1;
    await Bridge.fitZoom(dpr);
  };

  await onEvent<null>("screen-changed", async () => {
    await checkZoom();
    void Bridge.reposition();
    island.ensureRunning();
  });

  // A query only matches the ratio it was made for: once it changes, watch the
  // new one, or the next monitor's scale goes unnoticed and the zoom stays wrong.
  // One frame redraws Mochi at the new ratio, even while the loop is idle.
  const watchRatio = () => {
    window
      .matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`)
      .addEventListener?.("change", () => {
        watchRatio();
        void checkZoom();
        island.ensureRunning();
      }, { once: true });
  };
  watchRatio();

  window.addEventListener(
    "wheel",
    (e) => {
      if (e.ctrlKey) e.preventDefault();
    },
    { passive: false }
  );
  window.addEventListener("keydown", (e) => {
    if (e.ctrlKey && (e.key === "+" || e.key === "-" || e.key === "=" || e.key === "0")) {
      e.preventDefault();
    }
  });

  // Settings → Reload sounds: read the sounds folder again, and let them hear it.
  await onEvent<null>("sounds-changed", () => {
    void Sound.reload().then(() => Sound.play("pop"));
  });

  // The settings window writes preferences; apply them here without a restart.
  await onEvent<Settings>("settings-changed", (s) => {
    const previousMain = State.mainPillId;
    State.settings = { ...State.settings, ...s };
    applyLanguage();
    island.applySettings();
    State.loadIntegrationTasks();
    // A new main tool comes to the front, as on macOS.
    if (State.mainPillId !== previousMain) State.setFocus(State.mainPillId);
    void refreshConfigured();
  });

  registerHookHandlers(island);
  registerPhoneLink(island);
  registerIntegrationHandlers(island);
  registerShortcutHandlers(island, () => setPaused(false));
  registerVoiceHandlers();
  registerSpotifyHandlers(island);
  registerWhatsAppHandlers(island);
  // New versions: Rust offers the card, the island opens it when nothing else waits.
  await Updates.register(island);
  // Rust may have read Spotify before this page listened: ask once.
  if (State.settings.activeIntegrations.includes(SPOTIFY_ID)) {
    void Bridge.spotifyRefresh().then((s) => s && applySpotify(island, s));
  }

  // Monday recap: app start (greeting over), an agent starting work, waking up.
  const checkRecap = () => void Recap.check(island);
  // What's new, once after an update: when the greeting is over, or a few
  // seconds in when there is no greeting (the card waits for a quiet island).
  const whatsNew = () => void WhatsNew.launch(island);
  island.onGreetingDone = () => {
    checkRecap();
    whatsNew();
  };
  window.setTimeout(whatsNew, 8000);
  island.onWake = checkRecap;
  await onEvent<null>("recap-check", checkRecap);

  island.launch();

  // In a plain browser there is no wake strip behind the cursor: make the whole
  // page wake the island so the visuals can be checked with `npm run dev`.
  if (!IS_TAURI) {
    document.addEventListener("click", () => Sound.resume(), { once: true });
  }
}

void main();

/* Coucou for Windows — same palette, sizes and type scale as the macOS island.
   Every colour below is copied from the Swift views. */

:root {
  color-scheme: dark;

  /* After the Latin fonts: the scripts of the other interface languages —
     Devanagari and Bengali (Nirmala UI), Simplified Chinese (Microsoft YaHei)
     on Windows, the Noto families on Linux. Arabic and Cyrillic are in Segoe UI. */
  --font: system-ui, "Segoe UI Variable Text", "Segoe UI", "Segoe UI Emoji", "Nirmala UI",
    "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans", "Noto Sans Devanagari", "Noto Sans Bengali",
    "Noto Sans Arabic", "Noto Sans CJK SC", "Noto Sans SC", "Droid Sans Fallback", sans-serif;
  --mono: "Cascadia Mono", "Consolas", ui-monospace, monospace;

  --ink: #f5f6f8;        /* primary text */
  --ink-2: #f1f2f4;
  --dim: #9398a1;
  --dim-2: #8e939c;
  --dim-3: #6b7079;
  --dim-4: #5f646d;
  --dim-5: #4b5563;
  --card: #141518;
  --card-flat: #0e0f11;
  --tab-on: #1d1f23;
  --hairline: rgba(255, 255, 255, 0.035);
  --red: #f4505e;
  --red-text: #ff8d97;
  --green: #22c55e;
  --green-2: #34d399;
  --amber: #f5a524;
  --cyan: #22d3ee;
  --indigo: #6366f1;
  --pink: #f472b6;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  font-family: var(--font);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  cursor: default;
}

#root {
  position: fixed;
  inset: 0;
}

/* Invisible strip that wakes the island when it is hidden. */
#wake-strip {
  position: fixed;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 240px;
  height: 6px;
  background: transparent;
}

/* ── Island ─────────────────────────────────────────────────────────────── */

#island {
  position: absolute;
  top: 0;
  left: 50%;
  background: #000;
  border-radius: 0 0 14px 14px;
  overflow: visible;
  will-change: width, height, transform;
}

#island-clip {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
}

#bot-canvas,
#greeting-canvas {
  position: absolute;
  pointer-events: none;
}

/* The drop sequence. Sits under the header and takes over the island body; it
   cross-fades in and out, so the last frame stays up while the views return. */
#upload-layer {
  position: absolute;
  top: 0;
  width: 640px;
  height: 176px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease-in-out;
}

#upload-layer.on {
  opacity: 1;
}

#upload-canvas {
  position: absolute;
  inset: 0;
}

#upload-overlay {
  position: absolute;
  inset: 0;
  display: none;
}

/* Invisible hit areas over the buttons the canvas paints. */
.upload-hit {
  position: absolute;
  padding: 0;
  border: 0;
  border-radius: 13px;
  background: none;
  pointer-events: auto;
  cursor: pointer;
}

/* The ordinary views step aside while the sequence owns the body. The active
   view sets pointer-events back to auto, which beats the parent's none: it has
   to be switched off too, or its invisible card swallows the canvas buttons. */
#views.hidden-by-upload {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease-in-out;
}

#views.hidden-by-upload .view.on {
  pointer-events: none;
}

#bot-glow {
  position: absolute;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(6px);
  transition: opacity 0.4s ease-in-out, background 0.4s ease-in-out;
}

#countdown {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  height: 2px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.35);
  width: 0;
}

/* Compact 2×2 mini grid, to the right of the notch. */
#mini-grid {
  position: absolute;
  width: 29px;
  height: 29px;
  display: grid;
  grid-template-columns: 13px 13px;
  grid-auto-rows: 13px;
  gap: 3px;
  pointer-events: none;
  transition: opacity 0.25s ease-in-out;
}

/* Compact Claude plan gauge, next to the agent dots in the compact island. */
#compact-plan {
  --plan: #6b7079;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--plan) 14%, transparent);
  border-radius: 999px;
  background: #0e0f11;
  color: var(--dim-3);
  font: 600 10px var(--font);
  font-variant-numeric: tabular-nums;
  line-height: 12px;
  white-space: nowrap;
  cursor: pointer;
  pointer-events: auto;
  opacity: 0;
  transition: opacity 0.25s ease-in-out, right 0.2s ease, background 0.18s, border-color 0.18s, color 0.18s;
  user-select: none;
  z-index: 2;
}

#compact-plan:hover {
  background: color-mix(in srgb, var(--plan) 18%, transparent);
  border-color: color-mix(in srgb, var(--plan) 55%, transparent);
  color: color-mix(in srgb, var(--plan) 70%, white);
}

#compact-plan .compact-plan-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--plan);
  flex-shrink: 0;
}

/* Date and time in the middle of the compact island, between Mochi and the grid. */
#island-clock {
  position: absolute;
  left: 50px;
  right: 56px;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: rgba(255, 255, 255, 0.85);
  pointer-events: none;
  transition: opacity 0.25s ease-in-out;
}

/* The closed island's one line (core/closed.ts): the time, the plan, the song. */
#island-closed {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 16px;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  white-space: nowrap;
  color: rgba(245, 246, 248, 0.92);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.18s ease-in;
}

#island-closed.on {
  opacity: 1;
  transition: opacity 0.3s ease-out 0.12s;
}

#island-closed .text {
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

#island-closed .dot {
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

#island-closed.note::before {
  content: "♪";
  flex: 0 0 auto;
  font-size: 11px;
  color: #1ed760;
}

/* A mini Mochi: the slot is the body, the canvas is larger and overflows it so
   hands, badges and particles are not cut off. */
.mini {
  position: relative;
  display: inline-block;
  flex: 0 0 auto;
}

.mini canvas {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* ── Content shell (expanded) ───────────────────────────────────────────── */

#content {
  position: absolute;
  inset: 0;
  padding: 8px 10px 10px;
  display: flex;
  flex-direction: column;
  transition: opacity 0.2s ease-in-out;
}

#header {
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  margin: 0 -10px;
  transition: opacity 0.2s ease-in-out;
}

.tabs {
  display: flex;
  gap: 5px;
  padding-left: 14px;
}

.tab {
  width: 30px;
  height: 22px;
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  border-radius: 11px;
  color: var(--dim-2);
  cursor: default;
}

.tab:hover {
  background: rgba(255, 255, 255, 0.07);
  color: #b0b5be;
}

.tab.on {
  background: var(--tab-on);
  color: var(--ink);
}

.header-actions {
  margin-left: auto;
  display: flex;
  gap: 14px;
  padding-right: 16px;
}

.header-actions button {
  border: 0;
  background: transparent;
  color: var(--dim-2);
  display: grid;
  place-items: center;
  cursor: default;
}

.header-actions button.on {
  color: var(--ink);
}

#views {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
}

.view {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: scale(0.97);
  pointer-events: none;
  transition: opacity 0.16s ease-in;
}

.view.on {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
  transition: opacity 0.3s ease-out 0.16s, transform 0.3s cubic-bezier(0.3, 1.2, 0.4, 1) 0.16s;
}

/* A view that is not on is only transparent, not gone: an infinite animation
   inside it (the drop frame's marching dashes) would keep the webview
   repainting every frame for as long as the app runs, island hidden or not. */
.view:not(.on) * {
  animation-play-state: paused;
}

/* ── Cards ──────────────────────────────────────────────────────────────── */

.card {
  position: relative;
  height: 100%;
  border-radius: 20px;
  background: var(--card);
  border: 1px solid var(--hairline);
  overflow: hidden;
}

.card.wash::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    280px 280px at 50% 130%,
    var(--wash) 0%,
    rgba(0, 0, 0, 0) 70%
  );
  pointer-events: none;
}

.row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.dot {
  display: inline-block;
  border-radius: 50%;
  flex: 0 0 auto;
}

/* ── Buttons ────────────────────────────────────────────────────────────── */

.btn {
  font: 500 12.5px var(--font);
  padding: 7px 13px;
  border: 0;
  border-radius: 999px;
  cursor: default;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: transform 0.08s ease-out, background 0.12s ease-out;
}

.btn:active {
  transform: scale(0.94);
}

.btn.primary {
  background: var(--ink);
  color: #0b0c0e;
}

.btn.secondary {
  background: rgba(255, 255, 255, 0.09);
  color: var(--ink-2);
}

.btn.secondary:hover {
  background: rgba(255, 255, 255, 0.15);
}

.btn .kbd {
  font-size: 10.5px;
  padding: 0 4px;
  border-radius: 4px;
  opacity: 0.55;
}

.btn.primary .kbd {
  border: 1px solid rgba(0, 0, 0, 0.4);
}

.btn.secondary .kbd {
  border: 1px solid rgba(255, 255, 255, 0.4);
}

.link-btn {
  border: 0;
  background: transparent;
  font: 500 11px var(--font);
  cursor: default;
}

.icon-btn {
  width: 16px;
  height: 16px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  color: var(--dim-4);
  display: grid;
  place-items: center;
  cursor: default;
}

/* ── Overview ───────────────────────────────────────────────────────────── */

.overview {
  display: flex;
  gap: 10px;
  height: 100%;
}

.overview > .left {
  flex: 0 0 322px;
  width: 322px;
}

.overview > .right {
  flex: 1 1 auto;
}

.card-body {
  position: relative;
  z-index: 1;
  padding-top: 10px;
}

.who {
  padding: 0 36px 0 108px;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.who .name {
  font: 600 12px var(--font);
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.who .tool {
  font: 400 11px var(--font);
  color: var(--dim-2);
  white-space: nowrap;
}

.who .count {
  font: 400 11px var(--font);
  color: var(--dim-3);
  margin-left: auto;
  flex: 0 0 auto;
}

.jump {
  position: absolute;
  top: 8px;
  right: 10px;
  z-index: 2;
}

/* Folds a waiting permission card or question away without answering it. */
.fold {
  position: absolute;
  top: 8px;
  right: 10px;
  z-index: 2;
}

/* Ticker */

.ticker {
  position: relative;
  height: 44px;
  margin: 6px 12px 0 108px;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    #000 12%,
    #000 85%,
    transparent 100%
  );
  mask-image: linear-gradient(to bottom, transparent 0%, #000 12%, #000 85%, transparent 100%);
}

.ticker-row {
  position: absolute;
  left: 0;
  right: 0;
  height: 22px;
  display: flex;
  align-items: center;
  gap: 6px;
  transform-origin: left center;
  will-change: transform, opacity;
}

.ticker-row .tick-icon {
  width: 12px;
  display: grid;
  place-items: center;
  flex: 0 0 12px;
  color: var(--dim-2);
}

.ticker-row .tick-text {
  font: 500 13px var(--font);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Live diff step: file name, then +N −M right after it (TickerRowView). */
.ticker-row .tick-count {
  flex: 0 0 auto;
  margin-left: -6px; /* no row gap: the counts sit right after the name */
  font: 500 10px var(--mono);
  white-space: pre;
}

.ticker-row .tick-count .plus {
  color: var(--green);
}

.ticker-row .tick-count .minus {
  color: var(--red);
}

/* ── Diff card (overview, left card) — DiffCardView ─────────────────────── */

.diff-card {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 4px 10px 4px 108px;
}

.diff-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 0 3px;
  min-width: 0;
}

.diff-back {
  display: flex;
  align-items: center;
  gap: 3px;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  cursor: default;
}

.diff-back b {
  font: 600 12px var(--font);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.diff-head .grow {
  flex: 1 1 auto;
}

.diff-head .tick-count {
  flex: 0 0 auto;
  font: 500 10px var(--mono);
}

.diff-head .plus {
  color: var(--green);
}

.diff-head .minus {
  color: var(--red);
}

.diff-head .icon-btn {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
}

.diff-note {
  font: 400 10.5px var(--font);
  color: var(--dim-3);
}

.diff-lines {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: none;
  user-select: text;
}

.diff-lines::-webkit-scrollbar {
  display: none;
}

.diff-line {
  display: flex;
  min-height: 14px; /* an empty line still takes a row */
  font: 400 10.5px/1.35 var(--mono);
  color: var(--dim-3);
}

.diff-line .sym {
  flex: 0 0 12px;
  color: #454850;
}

.diff-line .txt {
  flex: 1 1 auto;
  min-width: 0;
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
}

.diff-line.added {
  background: rgba(34, 197, 94, 0.12);
  color: #86efac;
}

.diff-line.added .sym {
  color: var(--green);
}

.diff-line.removed {
  background: rgba(244, 80, 94, 0.12);
  color: #fca5a5;
}

.diff-line.removed .sym {
  color: var(--red);
}

/* Shimmer sweep, 2.2 s — same as TickerShimmerText / ShimmeringText */
.shimmer {
  background: linear-gradient(
    90deg,
    #7c818a 0%,
    #f2f3f5 40%,
    #7c818a 70%
  );
  background-size: 260% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer 2.2s linear infinite;
}

@keyframes shimmer {
  from {
    background-position: 130% 0;
  }
  to {
    background-position: -130% 0;
  }
}

/* ── Agent pills ────────────────────────────────────────────────────────── */

.pills {
  position: relative;
  z-index: 1;
  height: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-auto-rows: 28px;
  gap: 4px;
  align-content: center;
  padding: 0 8px;
}

.pill {
  position: relative;
  height: 28px;
  border-radius: 999px;
  background: var(--card-flat);
  border: 1px solid rgba(255, 255, 255, 0.14);
  display: flex;
  align-items: center;
  cursor: default;
  transition: transform 0.2s cubic-bezier(0.3, 1.2, 0.4, 1), background 0.18s, border-color 0.18s,
    box-shadow 0.18s, filter 0.18s;
}

.pill .mini {
  margin-left: 7px;
}

.pill .lbl {
  position: absolute;
  left: 0;
  right: 0;
  text-align: center;
  font: 600 10px var(--font);
  color: var(--dim-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding: 0 8px 0 34px;
  pointer-events: none;
}

.pill:hover {
  transform: scale(1.04);
  filter: brightness(1.06);
}

.pill-badge {
  position: absolute;
  top: -3px;
  right: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #0b0c0e;
  display: grid;
  place-items: center;
}

.pill-badge i {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #000;
}

.pill-badge svg {
  width: 6px;
  height: 6px;
}

/* ── Generic text blocks ────────────────────────────────────────────────── */

.title {
  font: 600 15px var(--font);
}

/* Claude's final message on the finished card: one line, never past the card. */
.title.one-line {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.sub {
  font: 400 13px var(--font);
  color: var(--dim);
}

.detail {
  font: 400 12px var(--font);
  color: var(--red-text);
}

.who-row {
  display: flex;
  align-items: center;
  gap: 7px;
  font: 400 12px var(--font);
  color: var(--dim-2);
}

.who-row .n {
  font: 600 12px var(--font);
  color: var(--ink);
}

.code {
  font: 400 12px var(--mono);
  color: #e8e9ec;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  padding: 5px 10px;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  user-select: text;
}

.stack {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
}

.actions {
  display: flex;
  gap: 8px;
}

/* Options to pick from when Claude Code asks a question. */
.actions.options {
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.question-text {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.btn.off {
  opacity: 0.4;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font: 400 11px var(--font);
  color: var(--dim-2);
}

/* ── Settings view (in-island) ──────────────────────────────────────────── */

.settings-rows {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.settings-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font: 400 12.5px var(--font);
  color: #c5c8cd;
}

.switch {
  position: relative;
  width: 32px;
  height: 18px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.15);
  flex: 0 0 32px;
  transition: background 0.18s;
  cursor: default;
  border: 0;
}

.switch.on {
  background: var(--green);
}

.switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.18s;
}

.switch.on::after {
  transform: translateX(14px);
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.2);
  width: 72px;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #fff;
}

.seg {
  display: flex;
  gap: 6px;
  margin-left: auto;
}

.seg button {
  font: 400 11px var(--font);
  padding: 3px 7px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--dim-3);
  cursor: default;
}

.seg button.on {
  background: #252830;
  color: var(--ink);
}

/* ── Utility ────────────────────────────────────────────────────────────── */

.grow {
  flex: 1 1 auto;
}

.nowrap {
  white-space: nowrap;
}

/* ── Chat (prompt view) ─────────────────────────────────────────────────── */

.chat-card {
  overflow: hidden;
}

.chat-body {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 16px 14px 84px;
}

.chip-row:empty {
  display: none;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  font: 400 11.5px var(--font);
  color: var(--ink-2);
  border: 1.5px solid rgba(255, 255, 255, 0.75);
  transform: scale(1.06);
  transition: border-color 0.3s ease-out 0.45s, transform 0.3s ease-out 0.45s;
}

.chip.settled {
  border-color: rgba(255, 255, 255, 0);
  transform: scale(1);
}

.chip-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: linear-gradient(135deg, #ff6b5b, #f7b32b, #2dd4a7, #38bdf8, #a78bfa);
}

.chat-log {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 2px 0;
}

.chat-row {
  display: flex;
}

.chat-row.user {
  justify-content: flex-end;
  padding-left: 32px;
}

.bubble {
  background: rgba(255, 255, 255, 0.13);
  border-radius: 12px;
  padding: 6px 10px;
  font: 400 12.5px var(--font);
  color: var(--ink-2);
  white-space: pre-wrap;
  user-select: text;
}

.reply {
  font: 400 12.5px var(--font);
  color: #b0b5be;
  white-space: pre-wrap;
  padding-right: 8px;
  user-select: text;
  /* Answers are Markdown blocks (views/markdown.ts), spaced as ChatMarkdownView. */
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

/* ── Markdown in the answers ─────────────────────────────────────────────── */

.md-p {
  font: 400 12.5px var(--font);
  color: #b0b5be;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.md-h {
  font: 600 13px var(--font);
  color: var(--ink-2);
  overflow-wrap: anywhere;
}

.md-h1 {
  font-weight: 700;
  font-size: 14px;
}

.reply strong {
  color: #e8e9ec;
  font-weight: 600;
}

.md-code {
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  font: 400 11.5px var(--mono);
  color: #c8cdd4;
}

.md-link {
  color: #60a5fa;
  text-decoration: underline;
  cursor: pointer;
}

.md-pre {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: #0d0e12;
}

.md-pre pre {
  flex: 1 1 auto;
  min-width: 0;
  font: 400 11px var(--mono);
  color: #c8cdd4;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.md-copy {
  flex: 0 0 22px;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--dim-3);
  cursor: default;
}

.md-copy:hover {
  color: var(--dim);
}

.md-copy.done {
  color: var(--green);
}

.md-item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.md-bullet {
  flex: 0 0 auto;
  min-width: 10px;
  font: 400 12.5px var(--font);
  color: var(--dim-3);
}

.md-quote {
  display: flex;
  align-items: stretch;
  gap: 8px;
}

.md-quote i {
  flex: 0 0 2px;
  border-radius: 1px;
  background: var(--dim-5);
}

.md-quote .md-p {
  color: #8a8f98;
}

.md-rule {
  width: 100%;
  border: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.3);
  opacity: 0.3;
}

.typing {
  display: flex;
  gap: 4px;
  padding: 4px 2px;
}

.typing i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--dim-3);
  animation: typing 0.9s ease-in-out infinite;
}

.typing i:nth-child(2) {
  animation-delay: 0.14s;
}

.typing i:nth-child(3) {
  animation-delay: 0.28s;
}

@keyframes typing {
  0%, 100% { transform: scale(0.6); }
  50% { transform: scale(1.2); }
}

/* ── Provider and model switcher (PromptView's model button) ─────────────── */

.model-row {
  display: flex;
  justify-content: flex-end;
  padding: 0 10px;
}

.model-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 100%;
  padding: 4px 8px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: #5c6370;
  cursor: default;
}

.model-btn:hover:not(:disabled),
.model-btn.open {
  background: rgba(255, 255, 255, 0.1);
}

.model-btn:disabled {
  opacity: 0.6;
}

.model-dot {
  flex: 0 0 6px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.model-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: 500 10.5px var(--font);
  color: #7b8089;
}

.picker {
  display: none;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border-radius: 12px;
  background: #16171b;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.chat-body.picking .picker {
  display: flex;
}

.chat-body.picking .chat-log,
.chat-body.picking .chip-row {
  display: none;
}

.picker-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.picker-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.06);
  font: 400 11.5px var(--font);
  color: #c8cdd4;
  cursor: default;
}

.picker-chip.on {
  font-weight: 600;
  color: var(--ink-2);
  /* Plain fallbacks for WebKitGTK builds without color-mix(). */
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.12);
  border-color: color-mix(in srgb, var(--accent) 50%, transparent);
  background: color-mix(in srgb, var(--accent) 18%, transparent);
}

.picker-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
}

.picker-rule {
  flex: 0 0 1px;
  background: rgba(255, 255, 255, 0.2);
  opacity: 0.4;
}

.picker-list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.picker-model {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #c8cdd4;
  font: 400 12px var(--font);
  text-align: left;
  cursor: default;
}

.picker-model:hover {
  background: rgba(255, 255, 255, 0.05);
}

.picker-model.on {
  color: var(--accent);
  background: rgba(255, 255, 255, 0.06);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

.picker-model-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.picker-status {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 4px 0;
  font: 400 11px var(--font);
  color: #8a8f98;
}

.picker-link {
  padding: 0;
  border: 0;
  background: none;
  color: #60a5fa;
  font: inherit;
  cursor: default;
}

.chat-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 12px;
}

.chat-input {
  flex: 1 1 auto;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  font: 400 13px var(--font);
  outline: none;
  cursor: text;
}

.chat-input::placeholder {
  color: var(--dim-3);
}

.send-btn {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  border: 0;
  border-radius: 50%;
  background: var(--ink);
  color: #0b0c0e;
  display: grid;
  place-items: center;
  cursor: default;
  transition: transform 0.08s ease-out;
}

.send-btn:active {
  transform: scale(0.94);
}

/* ── New Claude Code session (views/launch.ts, Mac LaunchView) ─────────── */

.launch-body {
  padding: 4px 16px 4px 98px;
  justify-content: center;
  gap: 8px;
}

.launch-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.launch-title {
  flex: 1 1 auto;
  min-width: 0;
  font: 600 14px var(--font);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.launch-project {
  flex: 0 1 auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 190px;
  padding: 4px 8px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: #c9cdd4;
  cursor: default;
}

.launch-project:hover,
.launch-project.open {
  background: rgba(255, 255, 255, 0.1);
}

.launch-project svg {
  flex: 0 0 auto;
}

.launch-project-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: 500 11px var(--font);
}

.launch-send:disabled {
  opacity: 0.4;
}

.launch-hint {
  font: 400 11px var(--font);
  color: var(--dim-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.launch-hint.is-failed {
  color: #f4505e;
}

.launch-menu {
  display: none;
  max-height: 72px;
}

.launch-body.choosing .launch-menu {
  display: flex;
}

.launch-body.choosing .launch-bar,
.launch-body.choosing .launch-hint {
  display: none;
}

/* ── Sessions on the drop card (views/session-drop.ts, Mac SessionDropTargets) */

#session-drop {
  position: absolute;
  inset: 0;
  display: none;
  pointer-events: none;
}

#session-drop.on {
  display: block;
}

#session-drop .sd-title {
  position: absolute;
  font: 500 10.5px var(--font);
  line-height: 14px;
  color: var(--dim-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#session-drop .sd-row {
  position: absolute;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: rgba(255, 255, 255, 0.07);
  color: #d5d7db;
  font: 400 11.5px var(--font);
  transition: background 0.12s ease-out, color 0.12s ease-out, border-color 0.12s ease-out;
}

#session-drop .sd-row span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

#session-drop .sd-row.over {
  color: #34d399;
  font-weight: 600;
  background: rgba(34, 197, 94, 0.16);
  border-color: rgba(34, 197, 94, 0.7);
}

/* ── Drop zone ──────────────────────────────────────────────────────────── */

.drop-card {
  background: var(--card-flat);
  border: 0;
}

.drop-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.drop-frame rect {
  stroke: rgba(255, 255, 255, 0.13);
  animation: dash-march 1.1s linear infinite, dash-breathe 7s ease-in-out infinite;
}

.drop-card.over {
  background: radial-gradient(200px 200px at 50% 100%, rgba(34, 197, 94, 0.13), transparent 70%),
    var(--card-flat);
}

.drop-card.over .drop-frame rect {
  stroke: rgba(34, 197, 94, 0.65);
  animation: dash-march 1.1s linear infinite;
}

@keyframes dash-march {
  to { stroke-dashoffset: -11; }
}

@keyframes dash-breathe {
  0%, 100% { stroke: rgba(255, 255, 255, 0.11); }
  50% { stroke: rgba(255, 255, 255, 0.15); }
}

.drop-body {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  padding-left: 196px;
}

.drop-title {
  font: 500 13px var(--font);
  color: #d5d7db;
  transition: color 0.2s;
}

.drop-card.over .drop-title {
  color: var(--green-2);
}

.drop-tags {
  display: flex;
  gap: 6px;
}

.drop-tags span {
  font: 400 11px var(--font);
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  color: #b9bdc4;
}

/* ── Uploading ──────────────────────────────────────────────────────────── */

.up-card {
  background: radial-gradient(260px 260px at 50% 140%, rgba(52, 211, 153, 0.14), transparent 70%),
    var(--card);
}

.up-card.done {
  background: radial-gradient(260px 260px at 50% 140%, rgba(52, 211, 153, 0.28), transparent 70%),
    var(--card);
}

.up-row {
  position: absolute;
  left: 26px;
  top: 36px;
  width: 526px;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font: 400 12.5px var(--font);
  color: #a9adb5;
}

.up-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.up-name.done {
  color: var(--green-2);
  font-weight: 600;
}

.up-pct {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  flex: 0 0 auto;
}

.up-track {
  position: absolute;
  left: 26px;
  top: 58px;
  width: 526px;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.09);
}

.up-fill {
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(90deg, #1fa87a, #34d399);
}

.up-glow {
  position: absolute;
  left: 0;
  top: -3px;
  width: 28px;
  height: 12px;
  border-radius: 50%;
  background: rgba(110, 231, 183, 0.45);
  filter: blur(5px);
  pointer-events: none;
}

/* ── Integration cards (overview, left card) ────────────────────────────── */

.left-body {
  position: relative;
  z-index: 1;
  height: 100%;
}

.int-card {
  padding: 10px 12px 0 108px;
  display: flex;
  flex-direction: column;
}

.int-head {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding-right: 24px;
}

.int-head b {
  font: 600 12px var(--font);
  color: var(--ink);
}

.int-head > span {
  font: 400 11px var(--font);
  color: var(--dim-2);
  white-space: nowrap;
}

.int-total {
