}

.int-ago {
  font: 400 10px var(--font);
  color: var(--dim-3);
  flex: 0 0 auto;
}

.int-sub {
  font: 400 10px var(--font);
  color: #4d5159;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
