}

.int-detail-head b {
  font: 600 11px var(--font);
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.int-badge {
  font: 500 10px var(--font);
