/* ── Plan usage: the pills in the header and the card behind them ────────────
   ClaudePlanHeaderPill / ClaudePlanCardView / CodexPlanCardView on the Mac.
   Nothing here applies until a pill is turned on in Settings. */

/* Off: takes no room, so the header is exactly as it shipped. */
.plan-pills {
  display: none;
  align-items: center;
  gap: 5px;
  /* .header-actions spaces its items 14px apart; the Mac puts 8px between
     the pills and the gear. */
  margin-right: -6px;
}

.plan-pills.on {
  display: flex;
}

/* Both pills: the Mac tightens the right side (icons 10px apart, pills 5px
   from the gear, 8px from the edge). */
.header-actions.both-plans {
  gap: 10px;
  padding-right: 8px;
}

.header-actions.both-plans .plan-pills {
  margin-right: -5px;
}

.header-actions .plan-pill {
  --plan: #6b7079;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--plan) 14%, transparent);
  border-radius: 999px;
  background: #0e0f11;
  color: var(--dim-3);
  font: 600 10px var(--font);
  line-height: 12px;
  white-space: nowrap;
  cursor: default;
  transition: background 0.18s, border-color 0.18s, color 0.18s;
}

.header-actions .plan-pill:hover,
.header-actions .plan-pill.active {
  background: color-mix(in srgb, var(--plan) 18%, transparent);
  border-color: color-mix(in srgb, var(--plan) 55%, transparent);
  color: color-mix(in srgb, var(--plan) 70%, white);
}

.plan-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.plan-card {
  position: relative;
  z-index: 1;
  padding-top: 10px;
}

.plan-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 36px 0 108px;
  white-space: nowrap;
}

.plan-head > * {
  flex: 0 0 auto;
}

.plan-title {
  font: 600 12px var(--font);
  color: var(--ink);
}

.plan-head > .plan-sub {
  flex: 0 1 auto; /* the one part that gives way, with an ellipsis */
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font: 400 11px var(--font);
  color: var(--dim-2);
}

.plan-rows {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 12px 0 108px;
}

.plan-row {
  display: flex;
  align-items: center;
  gap: 5px;
  font: 400 11px var(--font);
  white-space: nowrap;
}

.plan-label {
  flex: 0 0 40px;
  color: var(--dim-3);
}

.plan-bar {
  flex: 0 0 50px;
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.plan-fill {
  display: block;
  height: 100%;
  border-radius: 2px;
}

.plan-pct {
  flex: 0 0 30px;
  text-align: right;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #c5c8cd;
}

.plan-reset-icon {
  display: inline-flex;
  color: var(--dim-3);
}

.plan-reset {
  font-size: 10px;
  color: var(--dim-3);
}

.plan-none {
  color: var(--dim-3);
}

.plan-credits {
  font-weight: 600;
  color: #c5c8cd;
}

/* ── GitHub pulse (GitHubPulseCardView / GitHubDetailView) ─────────────── */

.gh-spark {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 0;
  padding: 0;
  background: transparent;
  font: 400 11px var(--font);
  color: var(--dim-2);
  white-space: nowrap;
  cursor: default;
  min-width: 0;
}

.gh-mini {
  display: inline-flex;
  gap: 2px;
}

.gh-mini i,
.gh-cell {
  width: 7px;
  height: 7px;
  border-radius: 1.5px;
  flex: 0 0 auto;
}

.int-stats.gh-rows {
  gap: 4px;
  padding-top: 6px;
}

.gh-stat {
  border: 0;
  padding: 0;
  background: transparent;
  width: 100%;
  text-align: left;
  cursor: default;
}

.gh-detail-head {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.gh-back {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  border: 0;
  padding: 0;
  background: transparent;
  font: 600 12px var(--font);
  color: var(--ink);
  white-space: nowrap;
  cursor: default;
  flex: 0 0 auto;
}

.gh-head-right {
  margin-left: auto;
  border: 0;
  padding: 0;
  background: transparent;
  font: 400 11px var(--font);
  color: var(--dim-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
