}

.np-track,
.np-fill {
  position: absolute;
  left: 0;
  top: 50%;
  height: 3px;
  transform: translateY(-50%);
  border-radius: 999px;
}

.np-track {
  width: 100%;
  background: rgba(255, 255, 255, 0.12);
