/* Scrollbars as on the Mac: a thin rounded thumb that floats on the page, no
   arrows and no track. (Chromium ignores these once scrollbar-width or
   scrollbar-color is set on the element, so those stay unset.) */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
  background: transparent;
}
::-webkit-scrollbar-track,
::-webkit-scrollbar-corner {
  background: transparent;
}
::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.16);
  border: 2px solid transparent;
  border-radius: 999px;
  background-clip: padding-box;
  min-height: 36px;
}
::-webkit-scrollbar-thumb:hover {
  background-color: rgba(255, 255, 255, 0.3);
}

/* Custom Windows/Linux edition: readable WhatsApp, on-demand media and movable island. */
.island-drag { cursor: ew-resize; touch-action: none; color: #a2a7af; margin: 0 auto; min-width: 36px; }
.overview.whatsapp-wide > .left { flex: 1 1 auto; width: auto; min-width: 0; }
.overview.whatsapp-wide > .right { display: none; }
.overview.whatsapp-wide .wa-card { padding: 14px 20px 12px 108px; }
.overview.whatsapp-wide .wa-name { font-size: 14px; }
.overview.whatsapp-wide .wa-text { font-size: 14px; line-height: 1.5; }
.overview.whatsapp-wide .wa-bubble { max-width: 100%; padding: 8px 10px; border-radius: 12px; }
.overview.whatsapp-wide .wa-messages { gap: 10px; scrollbar-width: thin; padding: 10px 8px 10px 0; }
.overview.whatsapp-wide .wa-field { font-size: 14px; max-height: 80px; }
.wa-time { display: block; text-align: right; font-size: 10px; color: #a2a7af; margin-top: 4px; }
.wa-load { padding: 8px 10px; border-radius: 8px; background: #173f30; color: #baf5d1; cursor: pointer; }
.wa-load:disabled { opacity: .65; cursor: wait; }
.wa-preview-media { display: block; max-width: 100%; width: 300px; max-height: 250px; object-fit: contain; border-radius: 8px; }
