// Just enough of a DOM for the views' helpers (views/dom.ts) to build nodes in
// Node. Writing `innerHTML` throws: a view that renders untrusted text must
// never parse it as markup, and a test that reaches for it fails loudly.

class FakeText {
  constructor(text) {
    this.nodeType = 3;
    this.data = String(text);
    this.parentNode = null;
  }
  get textContent() {
    return this.data;
  }
}

class FakeElement {
  constructor(tag, ns = null) {
    this.nodeType = 1;
    this.tagName = String(tag).toUpperCase();
    this.namespaceURI = ns;
    this.childNodes = [];
    this.parentNode = null;
    this.attributes = new Map();
    this.listeners = new Map();
    this.className = "";
    this.title = "";
    this.dataset = {};
    this.scrollTop = 0;
    this.scrollHeight = 0;
    this.style = { setProperty: (k, v) => (this.style[k] = v) };
    const el = this;
    this.classList = {
      add: (c) => (el.className = [...new Set([...el.className.split(" ").filter(Boolean), c])].join(" ")),
      remove: (c) => (el.className = el.className.split(" ").filter((x) => x && x !== c).join(" ")),
      contains: (c) => el.className.split(" ").includes(c),
      toggle: (c, on) => ((on ?? !el.classList.contains(c)) ? el.classList.add(c) : el.classList.remove(c)),
    };
  }
  set innerHTML(_) {
    throw new Error("innerHTML must never be used");
  }
  get innerHTML() {
    throw new Error("innerHTML must never be used");
  }
  set outerHTML(_) {
    throw new Error("outerHTML must never be used");
  }
  insertAdjacentHTML() {
    throw new Error("insertAdjacentHTML must never be used");
  }
  get parentElement() {
    return this.parentNode?.nodeType === 1 ? this.parentNode : null;
  }
  get children() {
    return this.childNodes.filter((n) => n.nodeType === 1);
  }
  get firstChild() {
    return this.childNodes[0] ?? null;
  }
  get textContent() {
    return this.childNodes.map((n) => n.textContent).join("");
  }
  set textContent(text) {
    this.childNodes = [];
    if (text !== "") this.append(new FakeText(text));
  }
  setAttribute(k, v) {
    this.attributes.set(k, String(v));
  }
  getAttribute(k) {
    return this.attributes.get(k) ?? null;
  }
  removeAttribute(k) {
    this.attributes.delete(k);
  }
  getBoundingClientRect() {
    return { left: 0, top: 0, width: 0, height: 0, right: 0, bottom: 0 };
  }
  setPointerCapture() {}
  addEventListener(type, fn) {
    this.listeners.set(type, [...(this.listeners.get(type) ?? []), fn]);
  }
  /** Calls the listeners of `type` with a minimal event. */
  fire(type) {
    const event = { type, defaultPrevented: false, preventDefault() { this.defaultPrevented = true; }, stopPropagation() {} };
    for (const fn of this.listeners.get(type) ?? []) fn(event);
    return event;
  }
  append(...nodes) {
    for (const n of nodes) {
      const node = typeof n === "string" ? new FakeText(n) : n;
      node.parentNode = this;
      this.childNodes.push(node);
    }
  }
  prepend(...nodes) {
    const added = nodes.map((n) => (typeof n === "string" ? new FakeText(n) : n));
    for (const node of added) node.parentNode = this;
    this.childNodes.unshift(...added);
  }
  replaceChildren(...nodes) {
    // As in a real DOM, the old children no longer have a parent.
    for (const old of this.childNodes) old.parentNode = null;
    this.childNodes = [];
    this.append(...nodes);
  }
  removeChild(node) {
    this.childNodes = this.childNodes.filter((n) => n !== node);
    node.parentNode = null;
    return node;
  }
  replaceWith(...nodes) {
    const parent = this.parentNode;
    if (!parent) return;
    for (const node of nodes) parent.insertBefore(node, this);
    this.remove();
  }
  get isConnected() {
    let node = this;
    while (node) { if (node === globalThis.document?.body) return true; node = node.parentNode; }
    return false;
  }
  pause() { this.paused = true; }
  remove() {
    this.parentNode?.removeChild(this);
  }
  /** `.a.b` class selectors only: the first descendant carrying every class. */
  querySelector(selector) {
    const wanted = selector.split(".").filter(Boolean);
    return [...this.walk()].find((e) => wanted.every((c) => e.classList.contains(c))) ?? null;
  }
  querySelectorAll(selector) {
    return [...this.walk()].filter((e) => selector.split(",").some((tag) => tag.startsWith(".") ? e.classList.contains(tag.slice(1)) : e.tagName === tag.toUpperCase()));
  }
  get firstElementChild() { return this.children[0] ?? null; }
  get nextElementSibling() {
    const all = this.parentNode?.children ?? [];
    return all[all.indexOf(this) + 1] ?? null;
  }
  insertBefore(node, reference) {
    node.parentNode?.removeChild(node);
    const at = reference ? this.childNodes.indexOf(reference) : this.childNodes.length;
    this.childNodes.splice(at, 0, node); node.parentNode = this;
    return node;
  }
  scrollIntoView() {}
  focus() {}
  select() {}
  /** Every descendant element, depth first. */
  *walk() {
    for (const c of this.children) {
      yield c;
      yield* c.walk();
    }
  }
  /** Descendants by tag name ("A") or class (".md-p"). */
  find(selector) {
    const match = selector.startsWith(".")
      ? (e) => e.classList.contains(selector.slice(1))
      : (e) => e.tagName === selector.toUpperCase();
    return [...this.walk()].filter(match);
  }
}

export function installFakeDom() {
  globalThis.HTMLImageElement = class { static [Symbol.hasInstance](node) { return node?.tagName === "IMG"; } };
  globalThis.requestAnimationFrame = (fn) => fn();
  globalThis.document = {
    createElement: (tag) => new FakeElement(tag),
    createElementNS: (ns, tag) => new FakeElement(tag, ns),
    createTextNode: (text) => new FakeText(text),
    body: new FakeElement("body"),
  };
  return { root: () => new FakeElement("div") };
}

// Display/voice identity is independent of the stable application identifier and hook paths.
use std::sync::{OnceLock, RwLock};
static NAME: OnceLock<RwLock<String>> = OnceLock::new();
pub fn clean(raw: &str) -> String {
    let text = raw.split_whitespace().collect::<Vec<_>>().join(" ");
    if text.is_empty() || text.chars().count() > 32 || !text.chars().any(char::is_alphanumeric)
        || !text.chars().all(|c| c.is_alphanumeric() || " ._-".contains(c)) { "Coucou".into() } else { text }
}
pub fn name() -> String { NAME.get_or_init(|| RwLock::new("Coucou".into())).read().unwrap().clone() }
pub fn set(raw: &str) { *NAME.get_or_init(|| RwLock::new("Coucou".into())).write().unwrap() = clean(raw); }
pub fn text(raw: String) -> String { raw.replace("Coucou", &name()) }
pub fn assistant() -> String { let n = name(); if n == "Coucou" { "Mochi".into() } else { n } }

#[cfg(windows)]
fn alias_path() -> std::path::PathBuf {
    let normalized = crate::voice::wake::normalize(&name());
    let slug = normalized.split_whitespace().collect::<Vec<_>>().join("-");
    let reserved = matches!(slug.as_str(), "con" | "prn" | "aux" | "nul") || (slug.len() == 4 && (slug.starts_with("com") || slug.starts_with("lpt")) && slug.ends_with(|c: char| c.is_ascii_digit()));
    let slug = if reserved { format!("app-{slug}") } else { slug };
    // A prefix for reserved names avoids Windows device names such as CON and NUL.
    crate::platform::config_dir().join("aliases").join(format!("{slug}.cmd"))
}
pub fn write_alias() -> Result<Option<String>, String> {
    #[cfg(windows)] {
        let path = alias_path();
        let parent = path.parent().ok_or("Invalid alias path")?;
        crate::platform::ensure_private_dir(parent).map_err(|e| e.to_string())?;
        let exe = std::env::current_exe().map_err(|e| e.to_string())?.to_string_lossy().replace('%', "%%");
        std::fs::write(&path, format!("@echo off\r\nstart \"\" \"{exe}\" %*\r\n")).map_err(|e| e.to_string())?;
        return Ok(Some(path.to_string_lossy().into_owned()));
    }
    #[cfg(not(windows))] { Ok(None) }
}

#[cfg(test)] mod tests {
    use super::*;
    #[test] fn names_are_bounded_and_never_paths_or_shell_expressions() {
        assert_eq!(clean("  Jarvis  Azul "), "Jarvis Azul");
        for invalid in ["../Jarvis", "x&calc", "x%PATH%", "---", ""] { assert_eq!(clean(invalid), "Coucou"); }
        assert_eq!(clean(&"a".repeat(33)), "Coucou");
    }
}

// The chat, whoever answers it: the conversation, the system prompt, and which
// provider a turn goes to. Each provider's own wire format lives in its module:
// claude.rs (Anthropic), openai_compat.rs (OpenAI, Google AI, OpenRouter) and
// local_chat.rs (Ollama, LM Studio, any OpenAI-compatible server).
//
// API keys never leave the credential store and file bytes never cross the IPC
// boundary: the island sends the question and gets the answer's text back.

use std::sync::Mutex;

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use tauri::AppHandle;

use crate::settings::Settings;
use crate::{claude, cli_relay, local_chat, openai_compat, secrets};

pub const ANTHROPIC: &str = "anthropic";

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum ChatContext {
    File { name: String, path: String },
    Window { app_name: String, title: String, url: Option<String> },
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ChatReply {
    pub text: String,
}

/// A model a provider offers, for the picker in the chat view.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelInfo {
    pub id: String,
    pub label: String,
}

// ── Conversation ──────────────────────────────────────────────────────────────

/// The conversation is kept twice: in the wire format of the provider that
/// answered last (Claude's carries web search blocks no other provider would
/// understand), and as plain text turns. Switching provider mid-conversation
/// rebuilds the history from the plain turns, so nothing in one provider's
/// format is ever sent to another.
#[derive(Default)]
pub struct Chat {
    inner: Mutex<Conversation>,
}

#[derive(Default)]
struct Conversation {
    /// Bumped by every reset, so an answer that lands after "New chat" is dropped.
    epoch: u64,
    /// The provider `native` belongs to.
    owner: Option<String>,
    native: Vec<Value>,
    /// `{"role", "content": text}` turns, the same whoever answered.
    plain: Vec<Value>,
}

/// What a provider needs to build one turn.
pub struct Turn {
    epoch: u64,
    provider: String,
    /// No earlier turn: the file or window context rides along with this one.
    pub first: bool,
    /// The earlier turns, in this provider's format.
    pub history: Vec<Value>,
}

impl Chat {
    pub fn reset(&self) {
        let mut c = self.inner.lock().unwrap();
        let epoch = c.epoch + 1;
        *c = Conversation { epoch, ..Default::default() };
    }

    /// Starts a turn with `provider`, converting the history if another
    /// provider answered the previous turns.
    pub fn begin(&self, provider: &str) -> Turn {
        let mut c = self.inner.lock().unwrap();
        if c.owner.as_deref() != Some(provider) {
            c.native = c.plain.clone();
            c.owner = Some(provider.to_string());
        }
        Turn {
            epoch: c.epoch,
            provider: provider.to_string(),
            first: c.plain.is_empty(),
            history: c.native.clone(),
        }
    }

    /// Records a finished turn: the user message and the answer in the
    /// provider's format, and their plain text. Only a successful turn is
    /// recorded, so the history always matches what the model saw.
    pub fn commit(&self, turn: &Turn, user: Value, assistant: Value, user_text: &str, answer: &str) {
        let mut c = self.inner.lock().unwrap();
        if c.epoch != turn.epoch || c.owner.as_deref() != Some(turn.provider.as_str()) {
            return;
        }
        c.native.push(user);
        c.native.push(assistant);
        c.plain.push(json!({ "role": "user", "content": user_text }));
        c.plain.push(json!({ "role": "assistant", "content": answer }));
    }
}

// ── System prompt ─────────────────────────────────────────────────────────────

/// Mochi's instructions. Greets the user by their first name when the account
/// has one worth using (identity.rs), and only claims web search where the
/// provider runs it (Claude).
pub fn system_prompt(web_search: bool) -> String {
    let base = system_prompt_for(crate::identity::first_name(), web_search);
    // The chat's Mail switch is on for this turn: how to write a mail plan.
    if crate::mail::MAIL_TURN.load(std::sync::atomic::Ordering::Relaxed) {
        return base + crate::mail::plan::INSTRUCTIONS;
    }
    base
}

fn system_prompt_for(first_name: Option<&str>, web_search: bool) -> String {
    let assistant = crate::branding::assistant();
    let opening = match first_name {
        Some(name) => format!("You are {assistant}, {name}'s personal AI assistant living at the top of their screen."),
        None => format!("You are {assistant}, a personal AI assistant living at the top of the user's screen."),
    };
    let abilities = if web_search {
        "You have web search access and can help with absolutely anything — research, coding, finding places, recommendations, tasks, questions."
    } else {
        "You can help with absolutely anything — research, coding, recommendations, tasks, questions. You have no web access: say so when something needs current information."
    };
    format!(
        "{opening} {abilities} \
Respond in the user's language. Be thorough and complete — use as much detail as the task requires. \
Use light Markdown when it helps: short paragraphs, bullet lists, **bold**, `inline code` and fenced code blocks. Avoid tables and big headings: the chat window is small."
    )
}

/// The window context line, as ClaudeService.chat() writes it.
pub fn window_line(app_name: &str, title: &str, url: Option<&str>) -> String {
    let mut text = format!("Context — App: {app_name}, Window: {title}");
    if let Some(url) = url {
        text.push_str(&format!(", URL: {url}"));
    }
    text
}

/// The plain-text record of what the user asked, context included.
pub fn plain_question(first: bool, context: Option<&ChatContext>, query: &str) -> String {
    match context.filter(|_| first) {
        Some(ChatContext::File { name, .. }) => format!("File: {name}\n\n{query}"),
        Some(ChatContext::Window { app_name, title, url }) => {
            format!("{}\n\n{query}", window_line(app_name, title, url.as_deref()))
        }
        None => query.to_string(),
    }
}

// ── Which provider ────────────────────────────────────────────────────────────

/// The model chosen for `provider`, or its default.
pub fn model_for(settings: &Settings, provider: &str) -> String {
    if provider == ANTHROPIC {
        let m = settings.model.trim();
        return if m.is_empty() { claude::DEFAULT_MODEL.to_string() } else { m.to_string() };
    }
    settings
        .chat_models
        .get(provider)
        .map(|m| m.trim().to_string())
        .filter(|m| !m.is_empty())
        .or_else(|| openai_compat::provider(provider).map(|p| p.default_model.to_string()))
        .unwrap_or_default()
}

/// A file rides along only if it is one of Coucou's own copies of a dropped
/// file (files.rs puts them in the inbox). The page names the path, so without
/// this any file the user can read could be sent to a chat provider.
fn checked_context(context: ChatContext) -> Result<ChatContext, String> {
    match context {
        ChatContext::File { name, path } => {
            let inbox = crate::files::inbox_dir();
            if !is_inside(&inbox, std::path::Path::new(&path)) {
                return Err(crate::i18n::t("Only a file dropped on the island can be sent with a question."));
            }
            Ok(ChatContext::File { name, path })
        }
        other => Ok(other),
    }
}

/// True when `path` is a regular file directly inside `dir`, both resolved
/// (no `..`, no symlink pointing out of it).
fn is_inside(dir: &std::path::Path, path: &std::path::Path) -> bool {
    let (Ok(dir), Ok(file)) = (dir.canonicalize(), path.canonicalize()) else { return false };
    file.parent() == Some(dir.as_path())
        && std::fs::symlink_metadata(&file).map(|m| m.is_file()).unwrap_or(false)
}

/// One chat turn with the provider chosen in the settings.
pub async fn send(
    app: &AppHandle,
    chat: &Chat,
    settings: &Settings,
    query: String,
    context: Option<ChatContext>,
) -> Result<ChatReply, String> {
    let context = context.map(checked_context).transpose()?;
    let provider = settings.chat_provider.as_str();
    let model = model_for(settings, provider);
    if cli_relay::uses_subscription(settings, provider) {
        return cli_relay::send(chat, provider, &model, query, context).await;
    }
    if provider == ANTHROPIC || provider.is_empty() {
        return claude::send(chat, &model, query, context).await;
    }
    if let Some(p) = openai_compat::provider(provider) {
        return openai_compat::send(chat, p, &model, query, context).await;
    }
    if let Some(server) = local_chat::server(settings, provider) {
        return local_chat::send(app, chat, &server, &model, query, context).await;
    }
    Err(format!("Unknown chat provider: {provider}"))
}

/// One turn of the phone's conversation (phone_link/chat_backend.rs): the same providers as
/// [`send`], with no file or window context and no `AppHandle`. `on_delta` gets the streamed
/// text so far, which only the model servers produce; the cloud providers answer all at once.
pub async fn send_for_phone(
    settings: &Settings,
    chat: &Chat,
    provider: &str,
    model: &str,
    query: String,
    on_delta: impl FnMut(String),
) -> Result<ChatReply, String> {
    if cli_relay::uses_subscription(settings, provider) {
        return cli_relay::send(chat, provider, model, query, None).await;
    }
    if provider == ANTHROPIC {
        return claude::send(chat, model, query, None).await;
    }
    if let Some(p) = openai_compat::provider(provider) {
        return openai_compat::send(chat, p, model, query, None).await;
    }
    if let Some(server) = local_chat::server(settings, provider) {
        return local_chat::send_with(chat, &server, model, query, None, on_delta).await;
    }
    Err(format!("Unknown chat provider: {provider}"))
}

/// The models `provider` offers. Asked only when the user opens the picker on
/// that provider, and only once it has a key (or, for a local server, an
/// address): nothing is sent anywhere before that.
pub async fn models(settings: &Settings, provider: &str) -> Result<Vec<ModelInfo>, String> {
    let no_key = || crate::i18n::t("No API key — add it in Settings.");
    if cli_relay::uses_subscription(settings, provider) {
        return Ok(cli_relay::models(provider));
    }
    if provider == ANTHROPIC {
        return claude::available_models().await;
    }
    if let Some(p) = openai_compat::provider(provider) {
        let key = secrets::get(p.key).ok_or_else(no_key)?;
        return openai_compat::models(p, &key).await;
    }
    if let Some(server) = local_chat::server(settings, provider) {
        return local_chat::models(&server).await;
    }
    Err(format!("Unknown chat provider: {provider}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn turn_texts(history: &[Value]) -> Vec<(String, Value)> {
        history
            .iter()
            .map(|m| (m["role"].as_str().unwrap().to_string(), m["content"].clone()))
            .collect()
    }

    #[test]
    fn a_turn_is_recorded_only_once_it_succeeds() {
        let chat = Chat::default();
        let t = chat.begin("anthropic");
        assert!(t.first);
        assert!(t.history.is_empty());
        // A failed turn records nothing: the next one is still the first.
        let t = chat.begin("anthropic");
        assert!(t.first);
        chat.commit(&t, json!({"role":"user","content":[{"type":"text","text":"hi"}]}), json!({"role":"assistant","content":[{"type":"text","text":"hello"}]}), "hi", "hello");
        let t = chat.begin("anthropic");
        assert!(!t.first);
        assert_eq!(t.history.len(), 2);
        assert!(t.history[0]["content"].is_array());
    }

    #[test]
    fn switching_provider_never_sends_claude_blocks_to_another_one() {
        let chat = Chat::default();
        let t = chat.begin("anthropic");
        let blocks = json!([
            {"type":"server_tool_use","id":"srvtoolu_1","name":"web_search","input":{"query":"x"}},
            {"type":"web_search_tool_result","tool_use_id":"srvtoolu_1","content":[]},
            {"type":"text","text":"Found it."}
        ]);
        chat.commit(&t, json!({"role":"user","content":[{"type":"text","text":"look"}]}), json!({"role":"assistant","content":blocks}), "look", "Found it.");

        let t = chat.begin("openai");
        assert!(!t.first);
        assert_eq!(
            turn_texts(&t.history),
            vec![("user".into(), json!("look")), ("assistant".into(), json!("Found it."))]
        );
        let raw = serde_json::to_string(&t.history).unwrap();
        assert!(!raw.contains("web_search"), "{raw}");

        // And back: Claude gets the plain turns too, including OpenAI's answer.
        chat.commit(&t, json!({"role":"user","content":"more"}), json!({"role":"assistant","content":"Sure."}), "more", "Sure.");
        let t = chat.begin("anthropic");
        assert_eq!(t.history.len(), 4);
        assert_eq!(t.history[3], json!({"role":"assistant","content":"Sure."}));
        assert!(!serde_json::to_string(&t.history).unwrap().contains("web_search"));
    }

    #[test]
    fn an_answer_that_lands_after_a_reset_or_a_switch_is_dropped() {
        let chat = Chat::default();
        let t = chat.begin("openai");
        chat.reset();
        chat.commit(&t, json!({"role":"user","content":"q"}), json!({"role":"assistant","content":"a"}), "q", "a");
        assert!(chat.begin("openai").first);

        let t = chat.begin("openai");
        let _other = chat.begin("google");
        chat.commit(&t, json!({"role":"user","content":"q"}), json!({"role":"assistant","content":"a"}), "q", "a");
        assert!(chat.begin("google").first);
    }

    #[test]
    fn the_prompt_greets_by_first_name_and_claims_web_search_only_for_claude() {
        let p = system_prompt_for(Some("Louis"), true);
        assert!(p.starts_with("You are Mochi, Louis's personal AI assistant living at the top of their screen."));
        assert!(p.contains("web search access"));
        assert!(p.contains("light Markdown"));
        let p = system_prompt_for(None, false);
        assert!(p.starts_with("You are Mochi, a personal AI assistant living at the top of the user's screen."));
        assert!(!p.contains("web search"));
        assert!(p.contains("no web access"));
    }

    #[test]
    fn context_goes_with_the_first_question_only() {
        let file = ChatContext::File { name: "a.txt".into(), path: "/x/a.txt".into() };
        assert_eq!(plain_question(true, Some(&file), "why?"), "File: a.txt\n\nwhy?");
        assert_eq!(plain_question(false, Some(&file), "why?"), "why?");
        let win = ChatContext::Window { app_name: "Code".into(), title: "main.rs".into(), url: None };
        assert_eq!(plain_question(true, Some(&win), "q"), "Context — App: Code, Window: main.rs\n\nq");
        assert_eq!(window_line("Edge", "Docs", Some("https://x.dev")), "Context — App: Edge, Window: Docs, URL: https://x.dev");
    }

    #[test]
    fn the_model_comes_from_the_settings_or_the_provider_default() {
        let mut s = Settings::default();
        assert_eq!(model_for(&s, "anthropic"), claude::DEFAULT_MODEL);
        assert_eq!(model_for(&s, "openai"), openai_compat::provider("openai").unwrap().default_model);
        assert_eq!(model_for(&s, "ollama"), "");
        s.chat_models.insert("openai".into(), " gpt-x ".into());
        s.chat_models.insert("ollama".into(), "llama3.2".into());
        s.model = "claude-haiku-4-5".into();
        assert_eq!(model_for(&s, "openai"), "gpt-x");
        assert_eq!(model_for(&s, "ollama"), "llama3.2");
        assert_eq!(model_for(&s, "anthropic"), "claude-haiku-4-5");
    }

    #[test]
    fn only_files_in_the_inbox_ride_along() {
        let base = std::env::temp_dir().join(format!("coucou-chat-ctx-{}", std::process::id()));
        let inbox = base.join("inbox");
        std::fs::create_dir_all(inbox.join("sub")).unwrap();
        std::fs::write(inbox.join("a.txt"), b"a").unwrap();
        std::fs::write(base.join("secret.txt"), b"s").unwrap();
        std::fs::write(inbox.join("sub").join("b.txt"), b"b").unwrap();
        assert!(is_inside(&inbox, &inbox.join("a.txt")));
        assert!(!is_inside(&inbox, &base.join("secret.txt")));
        assert!(!is_inside(&inbox, &inbox.join("..").join("secret.txt")));
        assert!(!is_inside(&inbox, &inbox.join("sub").join("b.txt")));
        assert!(!is_inside(&inbox, &inbox.join("missing.txt")));
        assert!(!is_inside(&inbox, &inbox));
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(base.join("secret.txt"), inbox.join("link.txt")).unwrap();
            assert!(!is_inside(&inbox, &inbox.join("link.txt")));
        }
        let _ = std::fs::remove_dir_all(&base);
    }
}

// Interface language for what Rust shows: the tray menu, the settings window
// title and the errors the webviews display. Same tables and same lookup as
// src/i18n/i18n.ts: strings keyed by their English text, from the Mac's catalog
// (strings.json, generated by scripts/gen-strings.mjs) and the Windows/Linux
// only ones (extra.json). A string missing in a language shows in English.
//
// The language is Settings.language when it is one of ours; "" follows the
// system: the languages the island's webview reports at launch, else (Linux)
// the LANGUAGE / LC_ALL / LC_MESSAGES / LANG variables, else English.

use serde_json::{Map, Value};
use std::collections::HashMap;
use std::sync::{OnceLock, RwLock};

pub const LANGUAGES: [&str; 14] = ["en", "zh-Hans", "hi", "es", "ar", "fr", "bn", "pt-BR", "ru", "id", "de", "tr", "ko", "ja"];

static MAC: &str = include_str!("../../src/i18n/strings.json");
static EXTRA: &str = include_str!("../../src/i18n/extra.json");

type Table = HashMap<String, Map<String, Value>>;

fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut out = Table::new();
        // extra.json goes last: it wins where both have a string.
        for source in [MAC, EXTRA] {
            let Ok(Value::Object(root)) = serde_json::from_str::<Value>(source) else { continue };
            let Some(Value::Object(strings)) = root.get("strings") else { continue };
            for (key, entry) in strings {
                if let Value::Object(langs) = entry {
                    out.insert(key.clone(), langs.clone());
                }
            }
        }
        out
    })
}

struct Current {
    picked: String,
    system: Vec<String>,
    resolved: &'static str,
}

fn state() -> &'static RwLock<Current> {
    static STATE: OnceLock<RwLock<Current>> = OnceLock::new();
    STATE.get_or_init(|| {
        let system = env_languages();
        let resolved = resolve("", &system);
        RwLock::new(Current { picked: String::new(), system, resolved })
    })
}

/// LANGUAGE (a list), then LC_ALL, LC_MESSAGES and LANG, as gettext reads them.
fn env_languages() -> Vec<String> {
    let mut out = Vec::new();
    if let Ok(list) = std::env::var("LANGUAGE") {
        out.extend(list.split(':').filter(|s| !s.is_empty()).map(str::to_string));
    }
    for name in ["LC_ALL", "LC_MESSAGES", "LANG"] {
        if let Ok(v) = std::env::var(name) {
            if !v.is_empty() && v != "C" && v != "POSIX" {
                out.push(v);
            }
        }
    }
    out
}

/// The language to show: `picked` when it is one of ours, else the first of
/// the system's languages we have, else English. Same rules as resolveLanguage
/// in src/i18n/i18n.ts.
pub fn resolve(picked: &str, system: &[String]) -> &'static str {
    if let Some(code) = LANGUAGES.iter().find(|c| **c == picked) {
        return code;
    }
    for raw in system {
        // "fr_FR.UTF-8" → "fr-fr"
        let tag = raw.split('.').next().unwrap_or("").replace('_', "-").to_lowercase();
        let base = tag.split('-').next().unwrap_or("");
        if base.is_empty() {
            continue;
        }
        if base == "zh" {
            let traditional = ["zh-hant", "zh-tw", "zh-hk", "zh-mo"].iter().any(|p| tag.starts_with(p));
            if traditional {
                continue;
            }
            return "zh-Hans";
        }
        if base == "pt" {
            return "pt-BR";
        }
        if let Some(code) = LANGUAGES.iter().find(|c| c.to_lowercase() == base) {
            return code;
        }
    }
    "en"
}

/// Records Settings.language. Returns true when the shown language changed.
pub fn set_picked(picked: &str) -> bool {
    let mut s = state().write().unwrap_or_else(|e| e.into_inner());
    s.picked = picked.to_string();
    let next = resolve(&s.picked, &s.system);
    std::mem::replace(&mut s.resolved, next) != next
}

/// Records the system's languages as the webview sees them. Returns true when
/// the shown language changed.
pub fn set_system(languages: Vec<String>) -> bool {
    let mut s = state().write().unwrap_or_else(|e| e.into_inner());
    if !languages.is_empty() {
        s.system = languages;
    }
    let next = resolve(&s.picked, &s.system);
    std::mem::replace(&mut s.resolved, next) != next
}

/// The language shown now.
pub fn current() -> &'static str {
    #[cfg(test)]
    return TEST_LANG.with(|c| c.get());
    #[cfg(not(test))]
    state().read().unwrap_or_else(|e| e.into_inner()).resolved
}

// Tests run in parallel and many check English text: each test thread has its
// own language, English unless the test picks another.
#[cfg(test)]
thread_local! {
    static TEST_LANG: std::cell::Cell<&'static str> = const { std::cell::Cell::new("en") };
}

fn interpolate(text: &str, vars: &[(&str, &str)]) -> String {
    let mut out = text.to_string();
    for (name, value) in vars {
        out = out.replace(&format!("{{{name}}}"), value);
    }
    out
}

fn lookup_in(lang: &str, key: &str) -> Option<&'static Value> {
    if lang == "en" {
        return None;
    }
    table().get(key)?.get(lang)
}

/// CLDR plural category of `n` (whole numbers) in `lang`.
fn plural_category(lang: &str, n: u64) -> &'static str {
    match lang {
        "zh-Hans" | "id" | "ko" | "ja" => "other",
        "fr" | "pt-BR" | "hi" | "bn" => {
            if n <= 1 { "one" } else { "other" }
        }
        "ru" => {
            let (m10, m100) = (n % 10, n % 100);
            if m10 == 1 && m100 != 11 {
                "one"
            } else if (2..=4).contains(&m10) && !(12..=14).contains(&m100) {
                "few"
            } else {
                "many"
            }
        }
        "ar" => match (n, n % 100) {
            (0, _) => "zero",
            (1, _) => "one",
            (2, _) => "two",
            (_, 3..=10) => "few",
            (_, 11..=99) => "many",
            _ => "other",
        },
        _ => {
            if n == 1 { "one" } else { "other" }
        }
    }
}

fn pick_plural(forms: &Map<String, Value>, category: &str) -> Option<String> {
    forms
        .get(category)
        .or_else(|| forms.get("other"))
        .or_else(|| forms.values().next())
        .and_then(Value::as_str)
        .map(str::to_string)
}

/// Marks an English key for a table built before it is shown (the tray's
/// labels): the code translates it with `t` when it shows it. The i18n test
/// (tests/i18n.test.mjs) finds the keys through it.
pub const fn n_(key: &'static str) -> &'static str {
    key
}

/// `key` (English text) in the shown language, else the English text.
pub fn t(key: &str) -> String {
    tf(key, &[])
}

/// `t` with `{name}` placeholders filled in.
pub fn tf(key: &str, vars: &[(&str, &str)]) -> String {
    let lang = current();
    let text = match lookup_in(lang, key) {
        Some(Value::String(s)) => s.clone(),
        Some(Value::Object(forms)) => pick_plural(forms, "other").unwrap_or_else(|| key.to_string()),
        _ => key.to_string(),
    };
    interpolate(&crate::branding::text(text), vars)
}

/// A count with its words: `tn("{count} file", "{count} files", n, &[])`.
#[allow(dead_code)]
pub fn tn(one: &str, other: &str, count: u64, vars: &[(&str, &str)]) -> String {
    let lang = current();
    let n = count.to_string();
    let mut all: Vec<(&str, &str)> = vars.to_vec();
    all.push(("count", &n));
    let text = match lookup_in(lang, other) {
        Some(Value::Object(forms)) => pick_plural(forms, plural_category(lang, count)),
        Some(Value::String(s)) => Some(s.clone()),
        _ => None,
    };
    let text = text.unwrap_or_else(|| if count == 1 { one.to_string() } else { other.to_string() });
    interpolate(&text, &all)
}

#[cfg(test)]
pub(crate) fn set_for_test(lang: &str) {
    TEST_LANG.with(|c| c.set(resolve(lang, &[])));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resolves_like_the_webview() {
        let sys = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(resolve("fr", &sys(&["ru"])), "fr");
        assert_eq!(resolve("", &sys(&["fr_FR.UTF-8"])), "fr");
        assert_eq!(resolve("", &sys(&["pt-PT"])), "pt-BR");
        assert_eq!(resolve("", &sys(&["zh-CN"])), "zh-Hans");
        assert_eq!(resolve("", &sys(&["zh-TW", "it", "es-MX"])), "es");
        assert_eq!(resolve("", &sys(&["it-IT"])), "en");
        assert_eq!(resolve("xx", &[]), "en");
    }

    #[test]
    fn looks_up_both_tables_and_falls_back_to_english() {
        set_for_test("fr");
        // From the Mac's catalog.
        assert_eq!(t("Allow"), "Autoriser");
        // From extra.json.
        assert_eq!(t("Open Coucou"), "Ouvrir Coucou");
        assert_eq!(t("A string nobody translated"), "A string nobody translated");
        assert_eq!(tf("Open {name}", &[("name", "Vercel")]), "Ouvrir Vercel");
        set_for_test("en");
        assert_eq!(t("Allow"), "Allow");
        assert_eq!(tf("Open {name}", &[("name", "Vercel")]), "Open Vercel");
    }

    #[test]
    fn plurals_follow_the_language() {
        set_for_test("en");
        assert_eq!(tn("✓ Connected · {count} model", "✓ Connected · {count} models", 1, &[]), "✓ Connected · 1 model");
        assert_eq!(tn("✓ Connected · {count} model", "✓ Connected · {count} models", 3, &[]), "✓ Connected · 3 models");
        set_for_test("es");
        assert_eq!(tn("✓ Connected · {count} model", "✓ Connected · {count} models", 1, &[]), "✓ Conectado · 1 modelo");
        assert_eq!(tn("✓ Connected · {count} model", "✓ Connected · {count} models", 4, &[]), "✓ Conectado · 4 modelos");
        assert_eq!(plural_category("ru", 21), "one");
        assert_eq!(plural_category("ru", 23), "few");
        assert_eq!(plural_category("ru", 25), "many");
        assert_eq!(plural_category("ar", 2), "two");
        set_for_test("en");
    }

    #[test]
    fn every_extra_string_has_every_language() {
        let Value::Object(root) = serde_json::from_str::<Value>(EXTRA).unwrap() else { panic!() };
        let Some(Value::Object(strings)) = root.get("strings") else { panic!("no strings") };
        for (key, entry) in strings {
            for lang in LANGUAGES.iter().filter(|l| **l != "en") {
                assert!(entry.get(*lang).is_some(), "{key:?} has no {lang}");
            }
        }
    }

    #[test]
    fn german_resolves_translates_and_selects_singular_only_for_one() {
        for tag in ["de", "de-DE", "de-AT", "de-CH", "de_DE.UTF-8"] {
            assert_eq!(resolve("", &[tag.to_string()]), "de");
        }
        assert_eq!(resolve("de", &["fr-FR".to_string()]), "de");
        assert_eq!(resolve("fr", &["de-DE".to_string()]), "fr");
        set_for_test("de");
        assert_eq!(t("Allow"), "Zulassen");
        assert_eq!(t("Deny"), "Ablehnen");
        assert_eq!(t("Open the chat"), "Chat öffnen");
        assert_eq!(tf("Uploading {name}", &[("name", "Grüße.pdf")]), "Grüße.pdf wird hochgeladen");
        assert_eq!(t("A string nobody translated"), "A string nobody translated");
        for count in [0, 1, 2, 21] {
            assert_eq!(plural_category("de", count), if count == 1 { "one" } else { "other" });
            let repo = if count == 1 { "Repository" } else { "Repositorys" };
            let model = if count == 1 { "Modell" } else { "Modelle" };
            assert_eq!(tn("{count} repo", "{count} repos", count, &[]), format!("{count} {repo}"));
            assert_eq!(tn("✓ Connected · {count} model", "✓ Connected · {count} models", count, &[]),
                format!("✓ Verbunden · {count} {model}"));
        }
        set_for_test("en");
    }

    #[test]
    fn turkish_resolves_translates_and_preserves_counted_nouns() {
        let system = |tag: &str| vec![tag.to_string()];
        assert_eq!(resolve("tr", &system("en-US")), "tr");
        for tag in ["tr", "tr-TR", "tr_TR.UTF-8"] {
            assert_eq!(resolve("", &system(tag)), "tr");
        }
        set_for_test("tr");
        assert_eq!(t("Allow"), "İzin ver");
        assert_eq!(t("Deny"), "Reddet");
        assert_eq!(t("Open the chat"), "Sohbeti aç");
        assert_eq!(tf("Uploading {name}", &[("name", "öğrenci.pdf")]), "öğrenci.pdf yükleniyor");
        assert_eq!(t("A string nobody translated"), "A string nobody translated");
        for n in [0, 1, 2, 21] {
            assert_eq!(plural_category("tr", n), if n == 1 { "one" } else { "other" });
            assert_eq!(tn("{count} repo", "{count} repos", n, &[]), format!("{n} depo"));
            assert_eq!(tn("✓ Connected · {count} model", "✓ Connected · {count} models", n, &[]),
                format!("✓ Bağlı · {n} model"));
        }
        set_for_test("en");
    }
}

