#[tauri::command]
fn move_island_horizontal(window: tauri::WebviewWindow, app: AppHandle, shared: State<Shared>, delta: f64, save: bool, reset: bool) -> Result<(), String> {
    if window.label() != island::WINDOW_LABEL { return Err("not from island".into()); }
    let pref = shared.settings.lock().unwrap().screen.clone();
    island::move_horizontal(&app, &pref, delta, save, reset);
    let collapsed = shared.gate.collapsed.load(Ordering::Relaxed);
    let size = *shared.gate.collapsed_size.lock().unwrap();
    island::apply_geometry(&app, &pref, collapsed.then_some(size));
    island::refresh_click_through(&app, &shared.gate);
    Ok(())
}

