// Island window: placement on the chosen display, the two window sizes
// (full panel / invisible wake strip), click-through and the cursor poll.
//
// There is no notch on a PC, so the island is a black shape drawn at the top
// centre of the main display inside a borderless, transparent, always-on-top
// window that never takes focus.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::time::Duration;

use serde::Serialize;
use tauri::{AppHandle, Emitter, Manager, Monitor, PhysicalPosition, PhysicalSize, WebviewWindow};

use crate::platform::{self, cursor_physical, left_button_down};

/// Logical size of the full window — the largest island view, like the macOS panel.
pub const PANEL_W: f64 = 720.0;
pub const PANEL_H: f64 = 580.0;
/// Logical size of the invisible strip that wakes the island when it is hidden
/// and the closed island is set to show nothing.
pub const STRIP_W: f64 = 240.0;
pub const STRIP_H: f64 = 6.0;

pub const WINDOW_LABEL: &str = "island";

/// Around the window, how far the cursor is still worth telling the page
/// about (Mochi's eyes follow it), in logical px. Past it the page hears once
/// that the cursor left, then nothing until it comes back: a cursor working in
/// another app costs neither messages nor island frames.
const NEAR_ZONE: f64 = 420.0;
/// The poll's period while the cursor is far from the island, in ms.
const FAR_PERIOD_MS: u64 = 50;

/// Whether a cursor at window-logical (x, y) is near a window of `size`.
fn is_near(x: f64, y: f64, size: (f64, f64)) -> bool {
    x >= -NEAR_ZONE && x <= size.0 + NEAR_ZONE && y >= -NEAR_ZONE && y <= size.1 + NEAR_ZONE
}

/// Margin around the island that still counts as "on the island", in logical px.
/// Wider than the macOS 6 pt because a click must never be swallowed.
const HIT_MARGIN: f64 = 14.0;

#[derive(Serialize, Clone)]
pub struct CursorPayload {
    pub x: f64,
    pub y: f64,
}

#[derive(Serialize, Clone)]
pub struct ScreenInfo {
    pub x: f64,
    pub y: f64,
    pub width: f64,
    pub height: f64,
    pub scale: f64,
}

/// The island shape in window-logical coordinates, pushed by the front end.
/// The poll thread owns the click-through decision so it lands in the same 16 ms
/// tick as the cursor read — an IPC round trip here loses clicks.
#[derive(Clone, Copy, Default)]
pub struct IslandRect {
    pub x: f64,
    pub y: f64,
    pub w: f64,
    pub h: f64,
}

/// Wakes / parks the cursor poll thread so a hidden island costs literally nothing.
pub struct PollGate {
    active: Mutex<bool>,
    cv: Condvar,
    pub collapsed: AtomicBool,
    /// The window's logical size while collapsed: the closed island the page
    /// draws, or the wake strip.
    pub collapsed_size: Mutex<(f64, f64)>,
    pub rect: Mutex<IslandRect>,
    /// Mirrors the window flag so we only call into the OS when it changes.
    ignoring: AtomicBool,
}

impl PollGate {
    pub fn new() -> Self {
        Self {
            active: Mutex::new(false),
            cv: Condvar::new(),
            collapsed: AtomicBool::new(true),
            collapsed_size: Mutex::new((STRIP_W, STRIP_H)),
            rect: Mutex::new(IslandRect::default()),
            ignoring: AtomicBool::new(false),
        }
    }

    pub fn set_rect(&self, rect: IslandRect) {
        *self.rect.lock().unwrap() = rect;
    }

    /// Forces the next poll tick to re-apply the flag (after a window resize).
    pub fn forget_ignore_state(&self) {
        self.ignoring.store(false, Ordering::Relaxed);
    }

    pub fn set_active(&self, on: bool) {
        let mut guard = self.active.lock().unwrap();
        *guard = on;
        self.cv.notify_all();
    }

    pub(crate) fn wait_until_active(&self) {
        let mut guard = self.active.lock().unwrap();
        while !*guard {
            guard = self.cv.wait(guard).unwrap();
        }
    }

    /// Waits until the gate opens or `timeout` passes; true when it is open.
    pub(crate) fn wait_active_for(&self, timeout: Duration) -> bool {
        let guard = self.active.lock().unwrap();
        if *guard {
            return true;
        }
        let (guard, _) = self.cv.wait_timeout(guard, timeout).unwrap();
        *guard
    }

    pub(crate) fn is_active(&self) -> bool {
        *self.active.lock().unwrap()
    }
}

pub fn window(app: &AppHandle) -> Option<WebviewWindow> {
    app.get_webview_window(WINDOW_LABEL)
}

fn monitor_contains(m: &Monitor, x: f64, y: f64) -> bool {
    let p = m.position();
    let s = m.size();
    x >= p.x as f64
        && x < (p.x + s.width as i32) as f64
        && y >= p.y as f64
        && y < (p.y + s.height as i32) as f64
}

/// A display's logical origin, the key `at:<x>,<y>` preferences are matched on.
/// Names are no good for that: two monitors of the same model share one.
fn logical_origin(m: &Monitor) -> (i32, i32) {
    let scale = m.scale_factor();
    let p = m.position();
    ((p.x as f64 / scale).round() as i32, (p.y as f64 / scale).round() as i32)
}

/// One entry of the "Island lives on" list in Settings.
#[derive(Serialize, Clone)]
pub struct MonitorChoice {
    pub key: String,
    pub label: String,
}

pub fn monitor_choices(app: &AppHandle) -> Vec<MonitorChoice> {
    let Ok(monitors) = app.available_monitors() else { return Vec::new() };
    monitors
        .iter()
        .map(|m| {
            let d = describe(m);
            MonitorChoice {
                key: d.key(),
                label: crate::i18n::tf(
                    "{name} — {width}×{height} at {x},{y}",
                    &[
                        ("name", &d.name),
                        ("width", &d.w.to_string()),
                        ("height", &d.h.to_string()),
                        ("x", &d.x.to_string()),
                        ("y", &d.y.to_string()),
                    ],
                ),
            }
        })
        .collect()
}

/// What a display is remembered by: its logical origin, plus its name and
/// logical size, so it is still found after the layout is rearranged or the
/// resolution changes (the Mac keeps the display's UUID for the same reason;
/// Tauri has no stable ID).
#[derive(Debug, Clone, PartialEq)]
struct DisplayId {
    name: String,
    x: i32,
    y: i32,
    w: i32,
    h: i32,
}

impl DisplayId {
    /// `at:<x>,<y>` stays first, so a preference saved before still matches.
    fn key(&self) -> String {
        format!("at:{},{}|{}|{}x{}", self.x, self.y, self.name.replace('|', " "), self.w, self.h)
    }
}

fn describe(m: &Monitor) -> DisplayId {
    let (x, y) = logical_origin(m);
    let scale = m.scale_factor();
    let s = m.size();
    DisplayId {
        name: m.name().cloned().unwrap_or_else(|| "Display".into()),
        x,
        y,
        w: (s.width as f64 / scale).round() as i32,
        h: (s.height as f64 / scale).round() as i32,
    }
}

/// Which display a saved `at:` preference points at, best match first: same
/// place and name; the same name and size elsewhere (layout rearranged); the
/// same name alone when unique (resolution changed); the same place. None
/// means unplugged, and the caller falls back to the primary display.
fn pick_display(pref: &str, displays: &[DisplayId]) -> Option<usize> {
    let rest = pref.strip_prefix("at:")?;
    let mut parts = rest.split('|');
    let (x, y) = parts.next()?.split_once(',')?;
    let (x, y) = (x.trim().parse::<i32>().ok()?, y.trim().parse::<i32>().ok()?);
    let name = parts.next();
    let size = parts.next().and_then(|s| {
        let (w, h) = s.split_once('x')?;
        Some((w.parse::<i32>().ok()?, h.parse::<i32>().ok()?))
    });
    let at = |d: &DisplayId| d.x == x && d.y == y;
    if let Some(name) = name {
        if let Some(i) = displays.iter().position(|d| at(d) && d.name == name) {
            return Some(i);
        }
        if let Some((w, h)) = size {
            if let Some(i) = displays.iter().position(|d| d.name == name && d.w == w && d.h == h) {
                return Some(i);
            }
        }
        let mut same_name = displays.iter().enumerate().filter(|(_, d)| d.name == name);
        if let (Some((i, _)), None) = (same_name.next(), same_name.next()) {
            return Some(i);
        }
    }
    displays.iter().position(at)
}

/// The display the island lives on: a chosen one, the primary one, or the one
/// under the cursor.
fn target_monitor(app: &AppHandle, pref: &str) -> Option<Monitor> {
    let monitors = app.available_monitors().ok()?;
    let ids: Vec<DisplayId> = monitors.iter().map(describe).collect();
    if let Some(i) = pick_display(pref, &ids) {
        return Some(monitors[i].clone());
    }
    if pref == "cursor" {
        if let Some((cx, cy)) = cursor_physical() {
            if let Some(m) = monitors.iter().find(|m| monitor_contains(m, cx, cy)) {
                return Some(m.clone());
            }
        }
    }
    app.primary_monitor()
        .ok()
        .flatten()
        .or_else(|| monitors.into_iter().next())
}

#[cfg(test)]
mod display_tests {
    use super::*;

    fn d(name: &str, x: i32, y: i32, w: i32, h: i32) -> DisplayId {
        DisplayId { name: name.into(), x, y, w, h }
    }

    #[test]
    fn a_display_is_found_again_after_changes() {
        let dell = d("DELL U2720Q", 1920, 0, 2560, 1440);
        let lap = d("eDP-1", 0, 0, 1920, 1200);
        let key = dell.key();
        assert_eq!(pick_display(&key, &[lap.clone(), dell.clone()]), Some(1));
        // Rearranged: the Dell moved to the left of the laptop.
        let moved = [d("eDP-1", 2560, 0, 1920, 1200), d("DELL U2720Q", 0, 0, 2560, 1440)];
        assert_eq!(pick_display(&key, &moved), Some(1));
        // Resolution changed, still the only Dell.
        let rescaled = [lap.clone(), d("DELL U2720Q", 1920, 0, 1920, 1080)];
        assert_eq!(pick_display(&key, &rescaled), Some(1));
        // Unplugged: nothing, so the caller falls back to the primary display.
        assert_eq!(pick_display(&key, &[lap.clone()]), None);
    }

    #[test]
    fn two_identical_monitors_are_told_apart_by_place() {
        let a = d("LG 27UL500", 0, 0, 1920, 1080);
        let b = d("LG 27UL500", 1920, 0, 1920, 1080);
        assert_eq!(pick_display(&b.key(), &[a.clone(), b.clone()]), Some(1));
        assert_eq!(pick_display(&a.key(), &[a, b]), Some(0));
    }

    #[test]
    fn preferences_saved_before_still_match() {
        let lap = d("eDP-1", 0, 0, 1920, 1200);
        let ext = d("HDMI-1", 1920, 0, 1920, 1080);
        assert_eq!(pick_display("at:1920,0", &[lap.clone(), ext.clone()]), Some(1));
        assert_eq!(pick_display("primary", &[lap, ext]), None);
        assert_eq!(pick_display("at:nonsense", &[]), None);
    }
}

/// Calculates the zoom correction factor so that 1 CSS pixel equals 1 window logical pixel.
/// If WebView2's devicePixelRatio differs from the window's scale factor (e.g. system text
/// scaling or multi-monitor DPI mismatch), adjusting the webview zoom ensures the island
/// canvas (PANEL_W / EXPANDED_W) fits within the window without clipping.
pub fn calculate_zoom_correction(current_zoom: f64, scale: f64, dpr: f64) -> Option<f64> {
    if dpr <= 0.0 || !dpr.is_finite() || scale <= 0.0 || !scale.is_finite() {
        return None;
    }
    if (dpr - scale).abs() / scale < 0.02 {
        return None;
    }
    let new_zoom = (current_zoom * (scale / dpr)).clamp(0.25, 4.0);
    Some(new_zoom)
}

#[cfg(test)]
mod zoom_tests {
    use super::*;

    #[test]
    fn zoom_correction_is_none_when_dpr_matches_window_scale() {
        assert_eq!(calculate_zoom_correction(1.0, 1.0, 1.0), None);
        assert_eq!(calculate_zoom_correction(1.0, 1.25, 1.25), None);
        // Within 2% threshold
        assert_eq!(calculate_zoom_correction(1.0, 1.0, 1.01), None);
    }

    #[test]
    fn zoom_correction_adjusts_for_dpi_mismatch() {
        // Issue #346: 100% scale display (scale 1.0) but WebView2 dpr = 1.25
        let zoom = calculate_zoom_correction(1.0, 1.0, 1.25);
        assert_eq!(zoom, Some(0.8));

        // 125% display with 125% text scale (dpr 1.5625 vs scale 1.25)
        let zoom = calculate_zoom_correction(1.0, 1.25, 1.5625);
        assert_eq!(zoom, Some(0.8));

        // 150% display with 100% webview dpr
        let zoom = calculate_zoom_correction(1.0, 1.5, 1.0);
        assert_eq!(zoom, Some(1.5));
    }

    #[test]
    fn only_a_cursor_near_the_island_is_followed() {
        let size = (PANEL_W, PANEL_H);
        assert!(is_near(360.0, 10.0, size));
        assert!(is_near(-400.0, PANEL_H + 400.0, size));
        assert!(!is_near(-500.0, 10.0, size));
        assert!(!is_near(360.0, PANEL_H + 900.0, size));
    }

    #[test]
    fn a_closed_island_stays_inside_the_panel() {
        assert_eq!(clamp_collapsed((160.0, 26.0)), (160.0, 26.0));
        assert_eq!(clamp_collapsed((5000.0, 900.0)), (PANEL_W, PANEL_H));
        assert_eq!(clamp_collapsed((0.0, -3.0)), (1.0, 1.0));
        assert_eq!(clamp_collapsed((f64::NAN, 26.0)), (PANEL_W, 26.0));
    }

    #[test]
    fn zoom_correction_handles_invalid_inputs() {
        assert_eq!(calculate_zoom_correction(1.0, 0.0, 1.0), None);
        assert_eq!(calculate_zoom_correction(1.0, 1.0, -1.0), None);
        assert_eq!(calculate_zoom_correction(1.0, f64::NAN, 1.0), None);
        assert_eq!(calculate_zoom_correction(1.0, 1.0, f64::INFINITY), None);
    }

    #[test]
    fn a_top_taskbar_moves_the_island_down_and_nothing_else_does() {
        // Taskbar at the bottom (or none): the work area starts at the top.
        assert_eq!(top_inset_from(0, 0), 0);
        // A 48 px taskbar at the top of a display placed at y = -1080.
        assert_eq!(top_inset_from(-1080, -1032), 48);
        // Nonsense from the system never pushes the island off the display.
        assert_eq!(top_inset_from(0, -20), 0);
        assert_eq!(top_inset_from(0, 900), 0);
    }
}


pub fn screen_info(app: &AppHandle, pref: &str) -> ScreenInfo {
    match target_monitor(app, pref) {
        Some(m) => {
            let scale = m.scale_factor();
            let p = m.position();
            let s = m.size();
            ScreenInfo {
                x: p.x as f64 / scale,
                y: p.y as f64 / scale,
                width: s.width as f64 / scale,
                height: s.height as f64 / scale,
                scale,
            }
        }
        None => ScreenInfo { x: 0.0, y: 0.0, width: 1920.0, height: 1080.0, scale: 1.0 },
    }
}

/// Places and sizes the window: the full panel, or `collapsed` to the size the
/// closed island needs (the wake strip when it shows nothing).
/// Windows: how far a taskbar docked at the top of this display (or another
/// app bar there) pushes the island down, read from the display's work area,
/// so the island sits under it (#956). An auto-hidden taskbar takes no work
/// area and moves nothing. Linux anchors the island to the screen edge: 0.
fn top_inset(m: &tauri::Monitor) -> i32 {
    if cfg!(windows) {
        top_inset_from(m.position().y, m.work_area().position.y)
    } else {
        0
    }
}

fn top_inset_from(monitor_y: i32, work_y: i32) -> i32 {
    let inset = work_y - monitor_y;
    if (0..200).contains(&inset) { inset } else { 0 }
}

// Horizontal anchor is kept independently of the current (open/closed) window size.
static HORIZONTAL: std::sync::OnceLock<Mutex<f64>> = std::sync::OnceLock::new();
fn horizontal(app: &AppHandle) -> &'static Mutex<f64> {
    HORIZONTAL.get_or_init(|| {
        let saved = app.path().app_data_dir().ok().and_then(|p| std::fs::read_to_string(p.join("island-position.txt")).ok())
            .and_then(|s| s.parse::<f64>().ok()).filter(|v| v.is_finite()).unwrap_or(0.5);
        Mutex::new(saved.clamp(0.0, 1.0))
    })
}

pub fn move_horizontal(app: &AppHandle, pref: &str, delta: f64, save: bool, reset: bool) {
    let Some(m) = target_monitor(app, pref) else { return };
    let mut anchor = horizontal(app).lock().unwrap();
    if reset { *anchor = 0.5; }
    else if delta.is_finite() { *anchor = (*anchor + delta * m.scale_factor() / m.size().width as f64).clamp(0.0, 1.0); }
    if save {
        if let Ok(dir) = app.path().app_data_dir() {
            let _ = std::fs::create_dir_all(&dir);
            let _ = std::fs::write(dir.join("island-position.txt"), anchor.to_string());
        }
    }
}

pub fn apply_geometry(app: &AppHandle, pref: &str, collapsed: Option<(f64, f64)>) {
    let Some(win) = window(app) else { return };
    let Some(m) = target_monitor(app, pref) else { return };

    let scale = m.scale_factor();
    let mp = *m.position();
    let ms = *m.size();

    let (lw, lh) = collapsed.map(clamp_collapsed).unwrap_or((PANEL_W, PANEL_H));
    let pw = (lw * scale).round().max(1.0) as u32;
    let ph = (lh * scale).round().max(1.0) as u32;
    let anchor = *horizontal(app).lock().unwrap();
    let max_left = (ms.width as i32 - pw as i32).max(0);
    let left = (anchor * ms.width as f64 - pw as f64 / 2.0).round() as i32;
    let x = mp.x + left.clamp(0, max_left);
    let y = mp.y + top_inset(&m);

    // GTK never sizes a non-resizable window below its natural size (200 px
    // here), so on Linux the 6 px wake strip would stay a 200 px block. tao
    // re-applies the config's `resizable: false` after the first configure, so
    // this is asked every time, just before the resize. Undecorated, the window
    // still offers the user nothing to resize it by. (Found by @YossiYad, #44.)
    #[cfg(target_os = "linux")]
    let _ = win.set_resizable(true);
    let _ = win.set_size(PhysicalSize::new(pw, ph));
    let _ = win.set_position(PhysicalPosition::new(x, y));
    let (lx, ly) = logical_origin(&m);
    platform::pin_to_monitor(&win, lx, ly);
    // Moving across displays can rescale the window: re-assert the physical size.
    let _ = win.set_size(PhysicalSize::new(pw, ph));
    let _ = win.set_always_on_top(true);

    // On Windows, moving across displays or waking from the strip can clamp or lag
    // the resize. If the physical inner size differs from what was requested, retry once.
    if let Ok(got) = win.inner_size() {
        if got.width != pw || got.height != ph {
            crate::log::line(format!(
                "window size mismatch: wanted {pw}x{ph}, got {}x{} (scale {scale}, monitor {}x{})",
                got.width, got.height, ms.width, ms.height
            ));
            let _ = win.set_size(PhysicalSize::new(pw, ph));
            let _ = win.set_position(PhysicalPosition::new(x, y));
        }
    }
}

/// A closed island never grows past the panel, and never shrinks below one
/// pixel (a zero-sized window can't be placed).
pub fn clamp_collapsed((w, h): (f64, f64)) -> (f64, f64) {
    let ok = |v: f64, max: f64| if v.is_finite() { v.clamp(1.0, max) } else { max };
    (ok(w, PANEL_W), ok(h, PANEL_H))
}

/// Position, size and scale of the monitor the island lives on. Any change here
/// means the island has to be placed again.
fn current_screen_key(app: &AppHandle) -> Option<(i32, i32, u32, u32, u64)> {
    let pref = app
        .try_state::<crate::Shared>()
        .map(|s| s.settings.lock().unwrap().screen.clone())
        .unwrap_or_else(|| "primary".into());
    let m = target_monitor(app, &pref)?;
    let p = m.position();
    let size = m.size();
    Some((p.x, p.y + top_inset(&m), size.width, size.height, m.scale_factor().to_bits()))
}

/// Emits `cursor` (window-logical coordinates) at ~60 Hz while the island is
/// visible. Parked on a condvar the rest of the time.
pub fn spawn_cursor_poll(app: AppHandle, gate: Arc<PollGate>) {
    std::thread::spawn(move || {
        let mut was_down = false;
        // Remembered across wakes so a display change while hidden is noticed the
        // moment the island comes back.
        let mut last_screen: Option<(i32, i32, u32, u32, u64)> = None;
        // Without a cursor to read (Linux) the loop only watches the display
        // layout, and twice a second is plenty for that: waking at 60 Hz just to
        // find no cursor costs CPU for nothing.
        let (period, screen_every) = if platform::CURSOR_POLL { (16, 30) } else { (500, 1) };
        loop {
            // Parked. Folded on Windows, a glance at the cursor four times a
            // second: on the closed island, it is told to wake up, whether or
            // not the webview delivers the pointer to such a small window.
            loop {
                if gate.wait_active_for(Duration::from_millis(250)) {
                    break;
                }
                if platform::CURSOR_POLL && gate.collapsed.load(Ordering::Relaxed) {
                    wake_if_hovered(&app, &gate);
                }
            }
            let mut last = (f64::MIN, f64::MIN);
            let mut ticks: u32 = 0;
            // The cursor was far at the last tick, and the page has been told.
            let mut far = false;
            while gate.is_active() {
                std::thread::sleep(Duration::from_millis(if far { FAR_PERIOD_MS } else { period }));
                if !gate.is_active() {
                    break;
                }

                // Monitors get plugged in, unplugged, rearranged and rescaled, and
                // an island pinned to coordinates that no longer exist is an island
                // nobody can reach. Checked about twice a second — the cursor poll
                // is already running, so this costs one monitor query.
                ticks = ticks.wrapping_add(1);
                if ticks % screen_every == 0 {
                    let now = current_screen_key(&app);
                    if now.is_some() && now != last_screen {
                        let first = last_screen.is_none();
                        last_screen = now;
                        if !first {
                            crate::log::line("display layout changed — repositioning".to_string());
                            let _ = app.emit_to(WINDOW_LABEL, "screen-changed", ());
                        }
                    }
                }

                let Some(win) = window(&app) else { continue };
                let Ok(origin) = win.outer_position() else { continue };
                let scale = win.scale_factor().unwrap_or(1.0);
                let Some((cx, cy)) = cursor_physical() else { continue };
                let x = (cx - origin.x as f64) / scale;
                let y = (cy - origin.y as f64) / scale;
                let size = match win.inner_size() {
                    Ok(s) => (s.width as f64 / scale, s.height as f64 / scale),
                    Err(_) => (PANEL_W, PANEL_H),
                };
                if (x - last.0).abs() < 1.0 && (y - last.1).abs() < 1.0 {
                    continue;
                }
                last = (x, y);

                // Click-through: the window only takes the mouse over the island
                // shape. A small entry margin means the flag is already off by the
                // time a moving cursor reaches a button.
                let r = *gate.rect.lock().unwrap();
                let on_island = r.w > 0.0
                    && x >= r.x - HIT_MARGIN
                    && x <= r.x + r.w + HIT_MARGIN
                    && y >= r.y - HIT_MARGIN
                    && y <= r.y + r.h + HIT_MARGIN;

                // A file being dragged has to be able to find us. WS_EX_TRANSPARENT
                // — what click-through is on Windows — hides the window from
                // WindowFromPoint, so OLE finds no drop target and shows the "no
                // drop" cursor. macOS has no such problem: AppKit delivers drags to
                // registered destinations whatever ignoresMouseEvents says. So while
                // a button is held anywhere over the panel, the whole panel takes
                // the mouse, which also makes the drop zone as forgiving as the Mac's.
                // A press may be the start of a drag: make sure the drop target is
                // ours before the file arrives.
                let down = left_button_down();
                if down && !was_down {
                    let handle = app.clone();
                    let _ = app.run_on_main_thread(move || platform::unblock_webview_drops(&handle));
                }
                was_down = down;

                let dragging = down
                    && x >= 0.0
                    && x <= size.0
                    && y >= 0.0
                    && y <= size.1;

                let accept = on_island || dragging;
                if gate.ignoring.load(Ordering::Relaxed) == accept {
                    // Under the gate's lock, and only while it is open: a tick
                    // still running as the island folds must not make the
                    // closed island click-through after set_collapsed made it
                    // take the mouse — nothing would ever wake it again.
                    let active = gate.active.lock().unwrap();
                    if !*active {
                        break;
                    }
                    gate.ignoring.store(!accept, Ordering::Relaxed);
                    platform::set_click_through(&win, !accept);
                }

                // Far from the island: the page hears it once, then nothing.
                let near = dragging || is_near(x, y, size);
                if !near && far {
                    continue;
                }
                far = !near;
                let _ = win.emit("cursor", CursorPayload { x, y });
            }
        }
    });
}

/// The cursor is on the folded window: it takes the mouse, and the page hears
/// `closed-hover` (it opens the compact island).
fn wake_if_hovered(app: &AppHandle, gate: &PollGate) {
    let Some(win) = window(app) else { return };
    let (Ok(origin), Ok(size), Some((cx, cy))) = (win.outer_position(), win.inner_size(), cursor_physical()) else { return };
    let x = cx - origin.x as f64;
    let y = cy - origin.y as f64;
    if x >= 0.0 && y >= 0.0 && x <= size.width as f64 && y <= size.height as f64 + 2.0 {
        gate.ignoring.store(false, Ordering::Relaxed);
        platform::set_click_through(&win, false);
        let _ = win.emit("closed-hover", ());
    }
}

/// Re-applies click-through after the window or the island changed shape.
///
/// With the cursor poll (Windows) the window takes the mouse again and the next
/// tick decides from the cursor. Without it (Linux) the input region is set to
/// the island itself, or to the whole wake strip while collapsed.
pub fn refresh_click_through(app: &AppHandle, gate: &PollGate) {
    if platform::CURSOR_POLL {
        set_ignore_cursor(app, false);
        gate.forget_ignore_state();
        return;
    }
    let Some(win) = window(app) else { return };
    let region = if gate.collapsed.load(Ordering::Relaxed) {
        // The closed island (or the wake strip) itself, never "the whole
        // window": if the window ever fails to shrink, the rest of it must not
        // swallow clicks meant for whatever sits under the top of the screen.
        let (w, h) = clamp_collapsed(*gate.collapsed_size.lock().unwrap());
        Some((0.0, 0.0, w, h))
    } else {
        let r = *gate.rect.lock().unwrap();
        if r.w <= 0.0 {
            // Nothing drawn yet: nothing takes the mouse.
            Some((0.0, 0.0, 0.0, 0.0))
        } else {
            let x0 = (r.x - HIT_MARGIN).max(0.0);
            let y0 = (r.y - HIT_MARGIN).max(0.0);
            let x1 = r.x + r.w + HIT_MARGIN;
            let y1 = r.y + r.h + HIT_MARGIN;
            Some((x0, y0, x1 - x0, y1 - y0))
        }
    };
    platform::set_input_region(&win, region);
}

pub fn set_ignore_cursor(app: &AppHandle, ignore: bool) {
    if let Some(win) = window(app) {
        platform::set_click_through(&win, ignore);
    }
}

// The two local WhatsApp gateways Coucou can talk to (port of WhatsAppProvider.swift). Each call
// goes to the URL set in Settings (127.0.0.1 by default) and nowhere else: no redirect, no proxy,
// no cookie, every answer read with a ceiling. Nothing of a message is logged.

use std::time::Duration;

use reqwest::{Method, Url};
use serde_json::{json, Value};

use super::gateway::{self, gowa, openwa, Kind, Link, Status};
use super::model::{self, Message};

/// Ceiling for one answer of the gateway (a QR PNG is about 2 KB, a page of messages a few).
const MAX_ANSWER: usize = 2 * 1024 * 1024;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum WaError {
    /// Nothing answers at that URL.
    Unreachable,
    /// Wrong user:pass (GOWA) or API key (OpenWA).
    Unauthorized,
    /// The gateway answered with an error (its own message, never a message's content).
    Refused(String),
    /// WhatsApp isn't linked yet.
    NotLoggedIn,
}

/// Percent-encodes one path segment (letters, digits and `-._~@` kept).
pub fn path_component(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        if b.is_ascii_alphanumeric() || b"-._~@".contains(&b) {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

/// The gateway's address as typed: http(s), a host, no `user:pass@`, nothing after the path.
pub fn parse_base(raw: &str) -> Option<Url> {
    let url = Url::parse(raw.trim()).ok()?;
    if !matches!(url.scheme(), "http" | "https") || url.host_str().is_none_or(str::is_empty) {
        return None;
    }
    if !url.username().is_empty() || url.password().is_some() {
        return None;
    }
    Some(url)
}

/// `base`'s path + `path`, the query added; None when the result left the gateway.
pub fn endpoint(base: &Url, path: &str, query: &[(&str, String)]) -> Option<Url> {
    let mut url = base.clone();
    let prefix = base.path().trim_matches('/');
    let full = if prefix.is_empty() { path.to_string() } else { format!("/{prefix}{path}") };
    url.set_path(&full);
    url.set_query(None);
    url.set_fragment(None);
    if !query.is_empty() {
        let mut pairs = url.query_pairs_mut();
        for (k, v) in query {
            pairs.append_pair(k, v);
        }
    }
    (url.host_str() == base.host_str() && url.port_or_known_default() == base.port_or_known_default()).then_some(url)
}

/// HTTP to the gateway: never a redirect, never a proxy, nothing kept between calls.
pub struct Http {
    base: Url,
    headers: Vec<(&'static str, String)>,
    client: reqwest::Client,
}

impl Http {
    pub fn new(base: Url, headers: Vec<(&'static str, String)>) -> Result<Http, WaError> {
        let client = reqwest::Client::builder()
            .redirect(reqwest::redirect::Policy::none())
            .no_proxy()
            .connect_timeout(Duration::from_secs(5))
            .build()
            .map_err(|_| WaError::Unreachable)?;
        Ok(Http { base, headers, client })
    }

    pub async fn call(&self, method: Method, path: &str, query: &[(&str, String)], body: Option<Value>, timeout: Duration) -> Result<(Vec<u8>, u16), WaError> {
        let url = endpoint(&self.base, path, query).ok_or(WaError::Unreachable)?;
        let mut req = self.client.request(method, url.clone()).timeout(timeout).header("Accept", "application/json");
        for (k, v) in &self.headers {
            req = req.header(*k, v);
        }
        if let Some(body) = body {
            req = req.header("Content-Type", "application/json").body(body.to_string());
        }
        let response = req.send().await.map_err(|_| WaError::Unreachable)?;
        // Second lock: an answer from anywhere but the gateway is not one.
        if response.url().host_str() != url.host_str() || response.url().port_or_known_default() != url.port_or_known_default() {
            return Err(WaError::Unreachable);
        }
        let code = response.status().as_u16();
        let data = crate::net::read_capped(response, MAX_ANSWER).await.map_err(|_| WaError::Unreachable)?;
        Ok((data, code))
    }

    async fn get(&self, path: &str, query: &[(&str, String)]) -> Result<(Vec<u8>, u16), WaError> {
        self.call(Method::GET, path, query, None, Duration::from_secs(10)).await
    }
}

fn basic_auth(credential: &str) -> String {
    format!("Basic {}", gateway::base64(credential.as_bytes()))
}

/// Either gateway, behind one face.
pub enum Provider {
    Gowa { http: Http, device: tokio::sync::Mutex<Option<String>> },
    Openwa { http: Http, session: tokio::sync::Mutex<Option<String>> },
}

/// A QR to show: a `data:image/png;base64,…` URL and how long it stays valid.
pub struct Qr {
    pub data_url: String,
    pub seconds: u64,
}

impl Provider {
    pub fn new(kind: Kind, base: Url, credential: Option<String>) -> Result<Provider, WaError> {
        let credential = credential.filter(|c| !c.is_empty());
        Ok(match kind {
            Kind::Gowa => {
                let headers = credential.filter(|c| c.contains(':')).map(|c| vec![("Authorization", basic_auth(&c))]).unwrap_or_default();
                Provider::Gowa { http: Http::new(base, headers)?, device: Default::default() }
            }
            Kind::Openwa => {
                let headers = credential.map(|c| vec![("X-API-Key", c)]).unwrap_or_default();
                Provider::Openwa { http: Http::new(base, headers)?, session: Default::default() }
            }
        })
    }

    // ── GOWA ──

    fn gowa_check(data: &[u8], code: u16) -> Result<(), WaError> {
        if code == 401 && gowa::error_code(data).as_deref() != Some("AUTHENTICATION_ERROR") {
            return Err(WaError::Unauthorized);
        }
        if code == 401 {
            return Err(WaError::NotLoggedIn);
        }
        if !(200..300).contains(&code) {
            return Err(WaError::Refused(gowa::error_code(data).unwrap_or_else(|| format!("HTTP {code}"))));
        }
        Ok(())
    }

    async fn gowa_device(http: &Http, slot: &tokio::sync::Mutex<Option<String>>) -> Result<(String, Status), WaError> {
        let (data, code) = http.get("/devices", &[]).await?;
        Self::gowa_check(&data, code)?;
        if let Some((id, status)) = gowa::device(&data) {
            *slot.lock().await = Some(id.clone());
            return Ok((id, status));
        }
        let (made, made_code) = http.call(Method::POST, "/devices", &[], Some(json!({"device_id": "coucou"})), Duration::from_secs(10)).await?;
        Self::gowa_check(&made, made_code)?;
        *slot.lock().await = Some("coucou".into());
        Ok(("coucou".into(), Status { link: Link::NeedsQr, me: None }))
    }

    async fn gowa_id(http: &Http, slot: &tokio::sync::Mutex<Option<String>>) -> Result<String, WaError> {
        if let Some(id) = slot.lock().await.clone() {
            return Ok(id);
        }
        Ok(Self::gowa_device(http, slot).await?.0)
    }

    async fn gowa_scoped(http: &Http, slot: &tokio::sync::Mutex<Option<String>>, method: Method, path: &str, query: &[(&str, String)], body: Option<Value>) -> Result<Vec<u8>, WaError> {
        let id = Self::gowa_id(http, slot).await?;
        let mut q: Vec<(&str, String)> = query.to_vec();
        q.push(("device_id", id));
        let (data, code) = http.call(method, path, &q, body, Duration::from_secs(10)).await?;
        Self::gowa_check(&data, code)?;
        Ok(data)
    }

    // ── OpenWA ──

    fn openwa_check(data: &[u8], code: u16) -> Result<(), WaError> {
        if code == 401 || code == 403 {
            return Err(WaError::Unauthorized);
        }
        if !(200..300).contains(&code) {
            return Err(WaError::Refused(openwa::error_message(data).unwrap_or_else(|| format!("HTTP {code}"))));
        }
        Ok(())
    }

    async fn openwa_start(http: &Http, id: &str, fallback: openwa::Session) -> Result<openwa::Session, WaError> {
        let (started, code) = http.call(Method::POST, &format!("/api/sessions/{}/start", path_component(id)), &[], None, Duration::from_secs(10)).await?;
        Self::openwa_check(&started, code)?;
        Ok(serde_json::from_slice::<Value>(&started).ok().as_ref().and_then(openwa::session).unwrap_or(fallback))
    }

    async fn openwa_session(http: &Http, slot: &tokio::sync::Mutex<Option<String>>) -> Result<openwa::Session, WaError> {
        let (data, code) = http.get("/api/sessions", &[]).await?;
        Self::openwa_check(&data, code)?;
        let all = openwa::sessions(&data);
        let known = slot.lock().await.clone();
        let pick = all
            .iter()
            .find(|s| s.status == "ready")
            .or_else(|| all.iter().find(|s| Some(&s.id) == known.as_ref()))
            .or_else(|| all.iter().find(|s| s.name == "coucou"))
            .or(all.first())
            .cloned();
        if let Some(s) = pick {
            *slot.lock().await = Some(s.id.clone());
            if openwa::needs_start(&s.status) {
                return Self::openwa_start(http, &s.id.clone(), s).await;
            }
            return Ok(s);
        }
        let (made, made_code) = http.call(Method::POST, "/api/sessions", &[], Some(json!({"name": "coucou"})), Duration::from_secs(10)).await?;
        Self::openwa_check(&made, made_code)?;
        let s = serde_json::from_slice::<Value>(&made)
            .ok()
            .as_ref()
            .and_then(openwa::session)
            .ok_or_else(|| WaError::Refused("session".into()))?;
        *slot.lock().await = Some(s.id.clone());
        Self::openwa_start(http, &s.id.clone(), s).await
    }

    async fn openwa_id(http: &Http, slot: &tokio::sync::Mutex<Option<String>>) -> Result<String, WaError> {
        if let Some(id) = slot.lock().await.clone() {
            return Ok(id);
        }
        Ok(Self::openwa_session(http, slot).await?.id)
    }

    async fn openwa_scoped(http: &Http, slot: &tokio::sync::Mutex<Option<String>>, method: Method, path: &str, query: &[(&str, String)], body: Option<Value>) -> Result<Vec<u8>, WaError> {
        let id = Self::openwa_id(http, slot).await?;
        let (data, code) = http.call(method, &format!("/api/sessions/{}{path}", path_component(&id)), query, body, Duration::from_secs(10)).await?;
        Self::openwa_check(&data, code)?;
        Ok(data)
    }

    // ── The face ──

    /// The link to WhatsApp (sets up the gateway's device or session the first time).
    pub async fn status(&self) -> Result<Status, WaError> {
        match self {
            Provider::Gowa { http, device } => Ok(Self::gowa_device(http, device).await?.1),
            Provider::Openwa { http, session } => Ok(openwa::status(&Self::openwa_session(http, session).await?)),
        }
    }

    /// The QR to scan; None when there is none to show (already linked, not ready yet).
    pub async fn qr(&self) -> Result<Option<Qr>, WaError> {
        match self {
            Provider::Gowa { http, device } => {
                let id = Self::gowa_id(http, device).await?;
                // GOWA answers once WhatsApp has handed it the first code: a few seconds.
                let (data, code) = http.call(Method::GET, &format!("/devices/{}/login", path_component(&id)), &[], None, Duration::from_secs(45)).await?;
                if gowa::error_code(&data).as_deref() == Some("ALREADY_LOGGED_IN") {
                    return Ok(None);
                }
                Self::gowa_check(&data, code)?;
                let Some((path, seconds)) = gowa::qr_path(&data) else { return Ok(None) };
                // The PNG is served by the gateway itself: fetched from the configured URL,
                // whatever host the link names.
                let (png, png_code) = http.get(&path, &[]).await?;
                if png_code != 200 || !png.starts_with(&[0x89, 0x50, 0x4E, 0x47]) {
                    return Ok(None);
                }
                // qr_duration is half the code's life: asking again sooner restarts the pairing.
                Ok(Some(Qr { data_url: gateway::png_data_url(&png), seconds: (seconds * 2).saturating_sub(5).max(20) }))
            }
            Provider::Openwa { http, session } => {
                let id = Self::openwa_id(http, session).await?;
                let (data, code) = http.get(&format!("/api/sessions/{}/qr", path_component(&id)), &[]).await?;
                if code == 400 {
                    return Ok(None); // not started, already linked, or not ready yet
                }
                Self::openwa_check(&data, code)?;
                Ok(openwa::qr_data_url(&data).map(|data_url| Qr { data_url, seconds: 15 }))
            }
        }
    }

    /// Tells the gateway to post new messages to Coucou's local webhook, signed with `secret`.
    pub async fn register_webhook(&self, url: &str, secret: &str) -> Result<(), WaError> {
        match self {
            Provider::Gowa { http, device } => {
                let id = Self::gowa_id(http, device).await?;
                let body = json!({"webhook_url": url, "webhook_secret": secret, "webhook_events": "message"});
                let (data, code) = http.call(Method::PATCH, &format!("/devices/{}/webhook", path_component(&id)), &[], Some(body), Duration::from_secs(10)).await?;
                Self::gowa_check(&data, code)
            }
            Provider::Openwa { http, session } => {
                let id = path_component(&Self::openwa_id(http, session).await?);
                let body = json!({"url": url, "events": ["message.received", "message.sent"], "secret": secret});
                let (list, list_code) = http.get(&format!("/api/sessions/{id}/webhooks"), &[]).await?;
                Self::openwa_check(&list, list_code)?;
                let hooks: Vec<Value> = serde_json::from_slice(&list).unwrap_or_default();
                let mine = hooks.iter().find(|h| h.get("url").and_then(Value::as_str) == Some(url)).and_then(|h| h.get("id")).and_then(Value::as_str);
                let (data, code) = match mine {
                    Some(hook) => http.call(Method::PUT, &format!("/api/sessions/{id}/webhooks/{}", path_component(hook)), &[], Some(body), Duration::from_secs(10)).await?,
                    None => http.call(Method::POST, &format!("/api/sessions/{id}/webhooks"), &[], Some(body), Duration::from_secs(10)).await?,
                };
                Self::openwa_check(&data, code)
            }
        }
    }

    /// Messages of every chat since `since_ms` (the polling fallback), oldest first.
    pub async fn recent_messages(&self, since_ms: i64, me: Option<&str>) -> Result<Vec<Message>, WaError> {
        let mut out = match self {
            Provider::Gowa { http, device } => {
                let chats = gowa::chats(&Self::gowa_scoped(http, device, Method::GET, "/chats", &[("limit", "20".into())], None).await?);
                let mut out = Vec::new();
                // Only the chats that moved since then (newest first from the gateway).
                for (jid, name, _) in chats.into_iter().take(8).filter(|c| c.2 > since_ms) {
                    let path = format!("/chat/{}/messages", path_component(&jid));
                    let data = Self::gowa_scoped(http, device, Method::GET, &path, &[("limit", "10".into()), ("start_time", gateway::iso_utc(since_ms))], None).await?;
                    out.extend(gowa::messages(&data, me).into_iter().map(|mut m| {
                        if m.chat_name.is_none() && !name.is_empty() && model::is_group(&jid) {
                            m.chat_name = Some(name.clone());
                        }
                        m
                    }));
                }
                out
            }
            Provider::Openwa { http, session } => {
                let q = [("since", since_ms.to_string()), ("limit", "50".into()), ("inlineMedia", "false".into())];
                openwa::messages(&Self::openwa_scoped(http, session, Method::GET, "/messages", &q, None).await?, me)
            }
        };
        out.sort_by_key(|m| m.date);
        Ok(out)
    }

    /// Download on explicit request. Only the configured GOWA origin may serve bytes.
    pub async fn media(&self, chat: &str, message: &str) -> Result<String, WaError> {
        let Provider::Gowa { http, device } = self else {
            return Err(WaError::Refused("Media viewing currently requires GOWA".into()));
        };
        let id = Self::gowa_id(http, device).await?;
        let (meta, code) = http.call(Method::GET,
            &format!("/message/{}/download", path_component(message)),
            &[("phone", chat.into()), ("device_id", id)], None, Duration::from_secs(45)).await?;
        Self::gowa_check(&meta, code)?;
        let value: Value = serde_json::from_slice(&meta).map_err(|_| WaError::Unreachable)?;
        let result = &value["results"];
        let raw = result["file_path"].as_str().unwrap_or("");
        // No absolute paths, traversal, external URLs or redirects.
        let path = raw.trim_start_matches('/');
        if !path.starts_with("statics/media/") || path.split('/').any(|s| s == ".." || s == ".")
            || path.contains(['\\', '%', '?', '#']) {
            return Err(WaError::Refused("Unsupported media path".into()));
        }
        let url = endpoint(&http.base, &format!("/{path}"), &[]).ok_or(WaError::Unreachable)?;
        let mut req = http.client.get(url).timeout(Duration::from_secs(45));
        for (key, value) in &http.headers { req = req.header(*key, value); }
        let response = req.send().await.map_err(|_| WaError::Unreachable)?;
        if !response.status().is_success() { return Err(WaError::Unreachable); }
        let mime = response.headers().get("content-type").and_then(|v| v.to_str().ok())
            .unwrap_or("").split(';').next().unwrap_or("").trim().to_lowercase();
        let allowed = matches!(mime.as_str(), "image/jpeg" | "image/png" | "image/webp" | "image/gif"
            | "audio/ogg" | "application/ogg" | "audio/mpeg" | "audio/mp4" | "audio/wav" | "audio/webm"
            | "video/mp4" | "video/webm" | "video/ogg");
        if !allowed { return Err(WaError::Refused("Unsupported media format".into())); }
        let bytes = crate::net::read_capped(response, 24 * 1024 * 1024).await.map_err(|_| WaError::Unreachable)?;
        Ok(format!("data:{mime};base64,{}", gateway::base64(&bytes)))
    }

    /// The latest `limit` messages of one chat, oldest first.
    pub async fn messages(&self, chat: &str, limit: usize, me: Option<&str>) -> Result<Vec<Message>, WaError> {
        let mut out = match self {
            Provider::Gowa { http, device } => {
                let path = format!("/chat/{}/messages", path_component(chat));
                gowa::messages(&Self::gowa_scoped(http, device, Method::GET, &path, &[("limit", limit.to_string())], None).await?, me)
            }
            Provider::Openwa { http, session } => {
                let q = [("chatId", openwa::chat_id(chat)), ("limit", limit.to_string()), ("inlineMedia", "false".into())];
                openwa::messages(&Self::openwa_scoped(http, session, Method::GET, "/messages", &q, None).await?, me)
            }
        };
        out.sort_by_key(|m| m.date);
        Ok(out)
    }

    /// Sends a text to an existing chat; the new message's id when the gateway gives it.
    pub async fn send(&self, text: &str, chat: &str) -> Result<Option<String>, WaError> {
        match self {
            Provider::Gowa { http, device } => {
                let data = Self::gowa_scoped(http, device, Method::POST, "/send/message", &[], Some(json!({"phone": chat, "message": text}))).await?;
                Ok(gowa::sent_id(&data))
            }
            Provider::Openwa { http, session } => {
                let data = Self::openwa_scoped(http, session, Method::POST, "/messages/send-text", &[], Some(json!({"chatId": openwa::chat_id(chat), "text": text}))).await?;
                Ok(serde_json::from_slice::<Value>(&data).ok().and_then(|v| v.get("messageId").and_then(Value::as_str).map(str::to_string)))
            }
        }
    }

    /// Marks the chat read up to `last_incoming` (the newest message received in it).
    pub async fn mark_read(&self, chat: &str, last_incoming: Option<&str>) -> Result<(), WaError> {
        match self {
            Provider::Gowa { http, device } => {
                let Some(id) = last_incoming else { return Ok(()) };
                let path = format!("/message/{}/read", path_component(id));
                Self::gowa_scoped(http, device, Method::POST, &path, &[], Some(json!({"phone": chat}))).await.map(|_| ())
            }
            Provider::Openwa { http, session } => {
                Self::openwa_scoped(http, session, Method::POST, "/chats/read", &[], Some(json!({"chatId": openwa::chat_id(chat)}))).await.map(|_| ())
            }
        }
    }

    /// A group's name, when the messages don't carry it.
    pub async fn group_name(&self, chat: &str) -> Option<String> {
        if !model::is_group(chat) {
            return None;
        }
        match self {
            Provider::Gowa { http, device } => {
                let data = Self::gowa_scoped(http, device, Method::GET, "/group/info", &[("group_id", chat.to_string())], None).await.ok()?;
                gowa::group_name(&data)
            }
            Provider::Openwa { http, session } => {
                let data = Self::openwa_scoped(http, session, Method::GET, &format!("/groups/{}", path_component(chat)), &[], None).await.ok()?;
                let v: Value = serde_json::from_slice(&data).ok()?;
                v.get("name").and_then(Value::as_str).filter(|s| !s.is_empty()).map(str::to_string)
            }
        }
    }
}

